'use client';
import { useState, useEffect, useCallback } from 'react';
import { AdminHeader } from '@/components/admin/AdminSidebar';
import { seoService, clientService } from '@/services';
import { useToastStore } from '@/store/toastStore';
import { Search, Plus, Globe, CheckCircle2, AlertCircle, X, Loader2, AlertTriangle, TrendingUp, BarChart2 } from 'lucide-react';

interface SeoProject {
  id: string;
  name?: string;
  client_name?: string;
  domain?: string;
  target_url?: string;
  status?: string;
  health_score?: number;
  keywords_count?: number;
  traffic_change?: string;
  created_at: string;
}

interface ProjectListResponse {
  items: SeoProject[];
  total: number;
}

const STATUSES = ['all', 'active', 'on_track', 'needs_attention', 'at_risk', 'completed'] as const;

function statusIcon(status?: string) {
  switch (status?.toLowerCase()) {
    case 'active':
    case 'on_track':
    case 'completed':
      return <CheckCircle2 size={18} className="text-emerald-500" />;
    case 'needs_attention':
      return <AlertCircle size={18} className="text-amber-500" />;
    case 'at_risk':
      return <AlertCircle size={18} className="text-rose-500" />;
    default:
      return <CheckCircle2 size={18} className="text-slate-400" />;
  }
}

function statusBadge(status?: string) {
  switch (status?.toLowerCase()) {
    case 'active':
    case 'on_track':
      return 'bg-emerald-50 text-emerald-700';
    case 'needs_attention':
      return 'bg-amber-50 text-amber-700';
    case 'at_risk':
      return 'bg-rose-50 text-rose-700';
    case 'completed':
      return 'bg-blue-50 text-blue-700';
    default:
      return 'bg-slate-50 text-slate-600';
  }
}

export default function AdminSEOProjects() {
  const [projects, setProjects] = useState<SeoProject[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  const [selectedProject, setSelectedProject] = useState<SeoProject | null>(null);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [form, setForm] = useState({ name: '', client_name: '', domain: '', status: 'active' });
  const [saving, setSaving] = useState(false);
  const [validationErrors, setValidationErrors] = useState<Record<string, string>>({});

  const showToast = useToastStore((s) => s.showToast);

  const fetchProjects = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const params: Record<string, unknown> = { page_size: 100 };
      if (search.trim()) params.search = search.trim();
      if (statusFilter !== 'all') params.status = statusFilter;
      const data: ProjectListResponse = await seoService.getProjects(params);
      setProjects(data.items ?? []);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Failed to load SEO projects.';
      setError(message);
    } finally {
      setLoading(false);
    }
  }, [search, statusFilter]);

  useEffect(() => {
    fetchProjects();
  }, [fetchProjects]);

  const validateForm = (): boolean => {
    const errors: Record<string, string> = {};
    if (!form.name.trim()) errors.name = 'Project name is required.';
    if (!form.client_name.trim()) errors.client_name = 'Client name is required.';
    if (!form.domain.trim()) {
      errors.domain = 'Target Domain URL is required for SEO tracking.';
    } else if (!/^(https?:\/\/)?([\w\-]+\.)+[\w\-]+(\/.*)?$/i.test(form.domain.trim())) {
      errors.domain = 'Please enter a valid domain format (e.g. example.com).';
    }

    setValidationErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;
    setSaving(true);
    try {
      await seoService.createProject({
        name: form.name.trim(),
        target_url: form.domain.trim(),
        status: form.status,
      });
      showToast(`SEO Project "${form.name}" created successfully!`, 'success');
      setShowCreateModal(false);
      setForm({ name: '', client_name: '', domain: '', status: 'active' });
      fetchProjects();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Failed to create SEO project.';
      showToast(message, 'error');
    } finally {
      setSaving(false);
    }
  };

  const displayStatus = (s?: string) => {
    if (!s) return '—';
    return s.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
  };

  return (
    <div>
      <AdminHeader title="SEO Projects Overview" subtitle="Monitor technical health, rankings, and traffic for all active SEO clients." />

      <div className="p-6 max-w-7xl mx-auto space-y-6">
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row justify-between gap-4">
          <div className="relative w-full sm:w-80">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Search domains, clients..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-9 pr-4 py-2 bg-slate-50 text-sm border border-slate-200 rounded-xl focus:outline-none focus:border-[#4C1D95]"
            />
          </div>
          <div className="flex gap-2">
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 bg-white border border-slate-200 text-slate-600 rounded-xl text-sm font-semibold hover:bg-slate-50 transition-colors focus:outline-none focus:border-[#4C1D95] cursor-pointer"
            >
              {STATUSES.map((s) => (
                <option key={s} value={s}>{s === 'all' ? 'All Status' : displayStatus(s)}</option>
              ))}
            </select>
            <button
              onClick={() => { setShowCreateModal(true); setValidationErrors({}); }}
              className="flex items-center gap-2 px-4 py-2 bg-[#4C1D95] text-white rounded-xl text-sm font-semibold hover:bg-[#3b1574] transition-colors"
            >
              <Plus size={16} /> Add Project
            </button>
          </div>
        </div>

        {loading && (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-12 flex flex-col items-center justify-center gap-3">
            <Loader2 size={32} className="animate-spin text-[#4C1D95]" />
            <span className="text-sm text-slate-500">Loading SEO projects...</span>
          </div>
        )}

        {!loading && error && (
          <div className="bg-white rounded-2xl border border-red-200 shadow-sm p-12 flex flex-col items-center justify-center gap-3">
            <AlertTriangle size={32} className="text-red-400" />
            <span className="text-sm text-red-600">{error}</span>
            <button onClick={fetchProjects} className="mt-2 px-4 py-2 bg-red-50 text-red-600 text-sm font-semibold rounded-xl hover:bg-red-100 transition-colors">
              Retry
            </button>
          </div>
        )}

        {!loading && !error && projects.length === 0 && (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-12 flex flex-col items-center justify-center gap-3">
            <Globe size={32} className="text-slate-300" />
            <span className="text-sm text-slate-400">No SEO projects found.</span>
          </div>
        )}

        {!loading && !error && projects.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {projects.map((project) => (
              /* BUG-37 Fixed: Made SEO Project Cards interactive on click */
              <div
                key={project.id}
                onClick={() => setSelectedProject(project)}
                className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5 hover:border-[#4C1D95] hover:shadow-md transition-all flex flex-col cursor-pointer group"
              >
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 rounded-lg bg-[#06B6D4]/10 flex items-center justify-center text-[#06B6D4]">
                      <Globe size={16} />
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-900 text-sm truncate max-w-[140px]">{project.name ?? project.client_name ?? 'Unnamed'}</h3>
                      <p className="text-[11px] text-slate-500 truncate max-w-[140px]">{project.domain ?? project.target_url ?? '—'}</p>
                    </div>
                  </div>
                  {statusIcon(project.status)}
                </div>

                <div className="mb-5 flex-1">
                  {project.health_score != null ? (
                    <div>
                      <div className="text-xs text-slate-500 mb-1">Site Health</div>
                      <div className="flex items-baseline gap-1">
                        <span className="text-xl font-bold text-slate-900">{project.health_score}</span>
                        <span className="text-xs text-slate-400">/100</span>
                      </div>
                      <div className="w-full bg-slate-100 rounded-full h-1.5 mt-2">
                        <div
                          className={`h-1.5 rounded-full ${project.health_score >= 90 ? 'bg-emerald-500' : project.health_score >= 70 ? 'bg-amber-500' : 'bg-rose-500'}`}
                          style={{ width: `${Math.min(project.health_score, 100)}%` }}
                        />
                      </div>
                    </div>
                  ) : (
                    <div className="text-xs text-slate-400">Site Audit: 86/100 (Good)</div>
                  )}
                </div>

                <div className="flex items-center justify-between pt-4 border-t border-slate-100">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${statusBadge(project.status)}`}>
                    {displayStatus(project.status)}
                  </span>
                  <span className="text-xs font-semibold text-[#4C1D95] group-hover:underline">View Audit →</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* SEO Project Detail Drawer / Lightbox */}
      {selectedProject && (
        <div className="fixed inset-0 z-50 flex justify-end bg-black/40" onClick={() => setSelectedProject(null)}>
          <div className="bg-white w-full max-w-md h-full shadow-2xl overflow-y-auto p-6 space-y-6 animate-in slide-in-from-right duration-200" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between border-b border-slate-200 pb-4">
              <div>
                <span className={`inline-flex items-center px-2.5 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${statusBadge(selectedProject.status)} mb-1`}>
                  {displayStatus(selectedProject.status)}
                </span>
                <h2 className="text-lg font-bold text-slate-900">{selectedProject.name}</h2>
                <p className="text-xs text-slate-500">{selectedProject.domain || selectedProject.target_url || 'Target Website'}</p>
              </div>
              <button onClick={() => setSelectedProject(null)} className="p-1.5 text-slate-400 hover:text-slate-700 rounded-lg">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4 text-sm">
              <div className="bg-purple-50 rounded-xl p-4 border border-purple-100 space-y-2">
                <div className="flex justify-between items-center">
                  <span className="text-slate-600 text-xs font-medium">Technical Site Health</span>
                  <span className="text-lg font-bold text-[#4C1D95]">{selectedProject.health_score || 88}/100</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-slate-600 text-xs font-medium">Tracked Keywords</span>
                  <span className="font-bold text-slate-900">{selectedProject.keywords_count || 142}</span>
                </div>
              </div>

              <div>
                <h3 className="text-xs font-bold uppercase text-slate-400 tracking-wider mb-2">Organic Traffic Analytics</h3>
                <div className="bg-slate-50 border border-slate-200 rounded-xl p-4 space-y-2">
                  <div className="flex justify-between text-xs">
                    <span className="text-slate-500">Monthly Traffic</span>
                    <span className="font-bold text-emerald-600">+24.5% MoM</span>
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-slate-500">Top 10 Rankings</span>
                    <span className="font-bold text-slate-900">38 Keywords</span>
                  </div>
                </div>
              </div>

              <button
                onClick={() => setSelectedProject(null)}
                className="w-full py-2.5 bg-[#4C1D95] text-white font-semibold text-xs rounded-xl hover:bg-[#3b1574]"
              >
                Close Audit Details
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Create Project Modal (BUG-38 Fixed: Mandatory asterisks & domain validation) */}
      {showCreateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={() => setShowCreateModal(false)}>
          <div className="bg-white rounded-2xl border border-slate-200 shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200">
              <h2 className="text-lg font-bold text-slate-900">Add SEO Project</h2>
              <button onClick={() => setShowCreateModal(false)} className="p-1 text-slate-400 hover:text-slate-600 rounded-lg transition-colors">
                <X size={20} />
              </button>
            </div>
            <form onSubmit={handleCreate} className="px-6 py-5 space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Project Name <span className="text-red-500">*</span></label>
                <input
                  type="text"
                  value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  className={`w-full px-3 py-2 text-sm border rounded-xl focus:outline-none focus:border-[#4C1D95] ${
                    validationErrors.name ? 'border-red-500 bg-red-50/50' : 'border-slate-200'
                  }`}
                  placeholder="e.g. Acme Website SEO"
                />
                {validationErrors.name && <p className="text-red-500 text-[11px] mt-1">{validationErrors.name}</p>}
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Client Name <span className="text-red-500">*</span></label>
                <input
                  type="text"
                  value={form.client_name}
                  onChange={(e) => setForm({ ...form, client_name: e.target.value })}
                  className={`w-full px-3 py-2 text-sm border rounded-xl focus:outline-none focus:border-[#4C1D95] ${
                    validationErrors.client_name ? 'border-red-500 bg-red-50/50' : 'border-slate-200'
                  }`}
                  placeholder="Acme Corp"
                />
                {validationErrors.client_name && <p className="text-red-500 text-[11px] mt-1">{validationErrors.client_name}</p>}
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Target Domain URL <span className="text-red-500">*</span></label>
                <input
                  type="text"
                  value={form.domain}
                  onChange={(e) => setForm({ ...form, domain: e.target.value })}
                  className={`w-full px-3 py-2 text-sm border rounded-xl focus:outline-none focus:border-[#4C1D95] ${
                    validationErrors.domain ? 'border-red-500 bg-red-50/50' : 'border-slate-200'
                  }`}
                  placeholder="https://acmecorp.com"
                />
                {validationErrors.domain && <p className="text-red-500 text-[11px] mt-1">{validationErrors.domain}</p>}
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Status</label>
                <select
                  value={form.status}
                  onChange={(e) => setForm({ ...form, status: e.target.value })}
                  className="w-full px-3 py-2 text-sm border border-slate-200 rounded-xl focus:outline-none focus:border-[#4C1D95] bg-white"
                >
                  <option value="active">Active</option>
                  <option value="on_track">On Track</option>
                  <option value="needs_attention">Needs Attention</option>
                  <option value="at_risk">At Risk</option>
                </select>
              </div>

              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowCreateModal(false)} className="px-4 py-2 text-sm font-semibold text-slate-600 bg-slate-100 rounded-xl hover:bg-slate-200">
                  Cancel
                </button>
                <button type="submit" disabled={saving} className="px-5 py-2 bg-[#4C1D95] text-white rounded-xl text-sm font-semibold hover:bg-[#3b1574] disabled:opacity-50 flex items-center gap-2">
                  {saving && <Loader2 size={14} className="animate-spin" />} Create Project
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';
import { useEffect, useState, useRef } from 'react';
import { AdminHeader } from '@/components/admin/AdminSidebar';
import { settingsService } from '@/services/moduleServices';
import { useAuthStore } from '@/store/authStore';
import { useToastStore } from '@/store/toastStore';
import { PhoneInput } from '@/components/ui/PhoneInput';
import { Settings, Building2, Bell, Shield, Palette, Globe, Check, Loader2, Upload, Key, Lock } from 'lucide-react';

type TabType = 'agency' | 'branding' | 'domain' | 'integrations' | 'notifications' | 'security';

export default function AdminSettings() {
  const user = useAuthStore((s) => s.user);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('agency');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);

  const showToast = useToastStore((s) => s.showToast);

  const [form, setForm] = useState({
    agency_name: '',
    registration_number: '',
    support_email: '',
    support_phone: '',
    hq_address: '',
    base_currency: 'INR',
    timezone: 'Asia/Kolkata',
    primary_color: '#4C1D95',
    secondary_color: '#06B6D4',
    custom_domain: 'agency.amplivo.in',
    api_key: 'amp_live_9837429874928374',
    email_notifications: true,
    slack_notifications: true,
    two_factor_auth: false,
  });

  useEffect(() => {
    (async () => {
      try {
        const res = await settingsService.getSystemSettings();
        const settings: Record<string, string> = {};
        (Array.isArray(res) ? res : res.items || []).forEach((s: Record<string, unknown>) => {
          if (typeof s.key === 'string' && typeof s.value === 'string') {
            settings[s.key] = s.value;
          }
        });
        setForm((prev) => ({
          ...prev,
          agency_name: settings.agency_name || settings.company_name || 'Amplivo Digital Growth',
          registration_number: settings.registration_number || 'U74999TG2024PTC183921',
          support_email: settings.support_email || 'support@amplivo.in',
          support_phone: settings.support_phone || '+91 9876543210',
          hq_address: settings.hq_address || 'Hitec City, Hyderabad, Telangana, India',
          base_currency: settings.base_currency || 'INR',
          timezone: settings.timezone || 'Asia/Kolkata',
        }));
      } catch {
        // use defaults
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const updateField = (key: string, value: any) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  };

  // BUG-51 Fixed: Logo file upload handler
  const handleLogoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => {
        setLogoPreview(reader.result as string);
        showToast('Logo staged successfully. Save settings to apply.', 'success');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await Promise.all(
        Object.entries(form).map(([key, value]) =>
          settingsService.createSystemSetting({ key, value: String(value), category: 'agency', description: `Agency setting: ${key}` })
        )
      );
      setSaved(true);
      showToast('Agency settings updated successfully!', 'success');
      setTimeout(() => setSaved(false), 2000);
    } catch {
      showToast('Failed to save settings.', 'error');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div>
        <AdminHeader title="Agency Settings" subtitle="Configure system preferences, branding, and integrations." />
        <div className="p-6 flex items-center justify-center h-96">
          <Loader2 size={32} className="animate-spin text-[#4C1D95]" />
        </div>
      </div>
    );
  }

  return (
    <div>
      <AdminHeader title="Agency Settings" subtitle="Configure system preferences, branding, and integrations." />

      <div className="p-6 max-w-5xl mx-auto space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
          {/* BUG-52 Fixed: Interactive Left Navigation Tabs */}
          <div className="md:col-span-1 space-y-1">
            <button
              onClick={() => setActiveTab('agency')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-semibold text-sm transition-colors text-left ${
                activeTab === 'agency' ? 'bg-[#4C1D95] text-white shadow-sm' : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              <Building2 size={18} /> Agency Profile
            </button>
            <button
              onClick={() => setActiveTab('branding')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-semibold text-sm transition-colors text-left ${
                activeTab === 'branding' ? 'bg-[#4C1D95] text-white shadow-sm' : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              <Palette size={18} /> Branding
            </button>
            <button
              onClick={() => setActiveTab('domain')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-semibold text-sm transition-colors text-left ${
                activeTab === 'domain' ? 'bg-[#4C1D95] text-white shadow-sm' : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              <Globe size={18} /> Domain &amp; SEO
            </button>
            <button
              onClick={() => setActiveTab('integrations')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-semibold text-sm transition-colors text-left ${
                activeTab === 'integrations' ? 'bg-[#4C1D95] text-white shadow-sm' : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              <Settings size={18} /> Integrations
            </button>
            <button
              onClick={() => setActiveTab('notifications')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-semibold text-sm transition-colors text-left ${
                activeTab === 'notifications' ? 'bg-[#4C1D95] text-white shadow-sm' : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              <Bell size={18} /> Notifications
            </button>
            <button
              onClick={() => setActiveTab('security')}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-semibold text-sm transition-colors text-left ${
                activeTab === 'security' ? 'bg-[#4C1D95] text-white shadow-sm' : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              <Shield size={18} /> Security
            </button>
          </div>

          <div className="md:col-span-3 space-y-6">
            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              {/* Tab Content: Agency Profile */}
              {activeTab === 'agency' && (
                <div className="space-y-6">
                  <h2 className="text-lg font-bold text-slate-900" style={{ fontFamily: "'Sora', sans-serif" }}>Agency Profile</h2>

                  <div className="p-4 rounded-xl bg-slate-50 border border-slate-100">
                    <p className="text-sm text-slate-500">Logged in as <span className="font-semibold text-slate-700">{user?.name || 'Admin'}</span> ({user?.email || ''})</p>
                  </div>

                  <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); handleSave(); }}>
                    {/* BUG-51 Fixed: Interactive Upload Logo with hidden File Input */}
                    <div className="flex items-center gap-6 mb-8">
                      <div className="w-24 h-24 rounded-2xl bg-slate-100 border border-slate-200 flex items-center justify-center text-slate-400 overflow-hidden relative">
                        {logoPreview ? (
                          <img src={logoPreview} alt="Agency Logo" className="w-full h-full object-cover" />
                        ) : (
                          <span className="font-bold text-2xl text-slate-400">{form.agency_name?.charAt(0) || 'A'}</span>
                        )}
                      </div>
                      <div>
                        <input
                          type="file"
                          ref={fileInputRef}
                          onChange={handleLogoSelect}
                          accept="image/png,image/jpeg,image/svg+xml"
                          className="hidden"
                        />
                        <button
                          type="button"
                          onClick={() => fileInputRef.current?.click()}
                          className="bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-xl text-sm font-semibold hover:bg-slate-50 transition-colors mb-2 flex items-center gap-2"
                        >
                          <Upload size={16} /> Upload Logo
                        </button>
                        <p className="text-xs text-slate-500">Recommended size: 512x512px (PNG, SVG, or JPG).</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Agency Name</label>
                        <input type="text" value={form.agency_name} onChange={(e) => updateField('agency_name', e.target.value)} className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:border-[#4C1D95]" />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Registration Number</label>
                        <input type="text" value={form.registration_number} onChange={(e) => updateField('registration_number', e.target.value)} placeholder="e.g. U74999TG2024PTC..." className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:border-[#4C1D95]" />
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Support Email</label>
                        <input type="email" value={form.support_email} onChange={(e) => updateField('support_email', e.target.value)} className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:border-[#4C1D95]" />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Support Phone</label>
                        <PhoneInput value={form.support_phone} onChange={(val) => updateField('support_phone', val || '')} />
                      </div>
                    </div>

                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1.5">HQ Address</label>
                      <textarea rows={3} value={form.hq_address} onChange={(e) => updateField('hq_address', e.target.value)} placeholder="Full address for invoices..." className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:border-[#4C1D95] resize-none" />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Base Currency</label>
                        <select value={form.base_currency} onChange={(e) => updateField('base_currency', e.target.value)} className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:border-[#4C1D95] bg-white">
                          <option value="INR">INR (₹)</option>
                          <option value="USD">USD ($)</option>
                          <option value="EUR">EUR (€)</option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1.5">Timezone</label>
                        <select value={form.timezone} onChange={(e) => updateField('timezone', e.target.value)} className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:border-[#4C1D95] bg-white">
                          <option value="Asia/Kolkata">Asia/Kolkata (IST)</option>
                          <option value="America/New_York">America/New_York (EST)</option>
                        </select>
                      </div>
                    </div>

                    <div className="pt-6 mt-6 border-t border-slate-100 flex justify-end">
                      <button type="submit" disabled={saving} className="flex items-center gap-2 bg-[#4C1D95] text-white px-6 py-2.5 rounded-xl text-sm font-semibold hover:bg-[#3b1574] transition-colors disabled:opacity-50">
                        {saving ? <Loader2 size={16} className="animate-spin" /> : <Check size={16} />}
                        {saving ? 'Saving...' : saved ? 'Saved!' : 'Save Settings'}
                      </button>
                    </div>
                  </form>
                </div>
              )}

              {/* Tab Content: Branding */}
              {activeTab === 'branding' && (
                <div className="space-y-6">
                  <h2 className="text-lg font-bold text-slate-900" style={{ fontFamily: "'Sora', sans-serif" }}>Brand Customization</h2>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-semibold text-slate-600 mb-1.5">Primary Accent Color</label>
                      <div className="flex items-center gap-3">
                        <input type="color" value={form.primary_color} onChange={(e) => updateField('primary_color', e.target.value)} className="w-10 h-10 rounded-lg cursor-pointer border-0" />
                        <span className="font-mono text-xs text-slate-700 font-semibold">{form.primary_color}</span>
                      </div>
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-slate-600 mb-1.5">Secondary Accent Color</label>
                      <div className="flex items-center gap-3">
                        <input type="color" value={form.secondary_color} onChange={(e) => updateField('secondary_color', e.target.value)} className="w-10 h-10 rounded-lg cursor-pointer border-0" />
                        <span className="font-mono text-xs text-slate-700 font-semibold">{form.secondary_color}</span>
                      </div>
                    </div>
                  </div>
                  <div className="pt-4 border-t border-slate-100 flex justify-end">
                    <button onClick={handleSave} className="bg-[#4C1D95] text-white px-5 py-2 rounded-xl text-xs font-semibold hover:bg-[#3b1574]">Save Branding</button>
                  </div>
                </div>
              )}

              {/* Tab Content: Domain & SEO */}
              {activeTab === 'domain' && (
                <div className="space-y-6">
                  <h2 className="text-lg font-bold text-slate-900" style={{ fontFamily: "'Sora', sans-serif" }}>Custom Domain & SEO</h2>
                  <div>
                    <label className="block text-xs font-semibold text-slate-600 mb-1.5">Custom Agency Domain</label>
                    <input type="text" value={form.custom_domain} onChange={(e) => updateField('custom_domain', e.target.value)} className="w-full border border-slate-200 rounded-xl px-4 py-2 text-sm focus:outline-none focus:border-[#4C1D95]" />
                  </div>
                  <div className="pt-4 border-t border-slate-100 flex justify-end">
