                </div>

                {/* Offices */}
                <div className="grid grid-cols-2 gap-3">
                  {offices.map((o) => (
                    <div key={o.city} className={`bg-white rounded-xl p-4 border ${o.primary ? 'border-[#4C1D95]/30' : 'border-slate-200'}`}>
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-lg">{o.flag}</span>
                        <span className="font-semibold text-slate-900 text-sm">{o.city}</span>
                        {o.primary && <span className="text-[10px] bg-[#4C1D95]/10 text-[#4C1D95] px-1.5 py-0.5 rounded-full font-semibold">HQ</span>}
                      </div>
                      <p className="text-slate-500 text-[11px] leading-tight">{o.address}</p>
                    </div>
                  ))}
                </div>
              </div>
            </AnimateOnScroll>
          </div>
        </div>
      </section>

      <Footer />
    </main>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import Link from 'next/link';
import {
  Search, Building2, Eye, Mail, Phone, IndianRupee,
  Calendar, Briefcase, CheckCircle, Clock, AlertCircle
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';

export default function CrmClientsPage() {
  const { clients, projects } = useCrmStore();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('All');

  const filtered = useMemo(() => {
    return clients
      .filter(c => {
        const q = search.toLowerCase();
        const matchSearch = !q ||
          c.company.toLowerCase().includes(q) ||
          c.firstName.toLowerCase().includes(q) ||
          c.lastName.toLowerCase().includes(q) ||
          c.clientId.toLowerCase().includes(q);
        const matchStatus = statusFilter === 'All' || c.status === statusFilter;
        return matchSearch && matchStatus;
      })
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [clients, search, statusFilter]);

  const stats = useMemo(() => {
    return {
      total: clients.length,
      active: clients.filter(c => c.status === 'Active').length,
      onboarding: clients.filter(c => c.status === 'Onboarding').length,
      churned: clients.filter(c => c.status === 'Churned').length,
    };
  }, [clients]);

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Clients</h1>
          <p className="text-sm text-slate-500 mt-0.5">Manage your active client portfolio</p>
        </div>
        <div className="flex gap-4">
          <div className="text-right">
            <p className="text-xs text-slate-500">Active Retainer</p>
            <p className="text-lg font-bold text-emerald-400">
              ₹{clients.filter(c => c.status === 'Active').reduce((sum, c) => sum + c.monthlyRetainer, 0).toLocaleString('en-IN')}/mo
            </p>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="flex gap-2 bg-[#12141f] p-1 rounded-lg border border-white/5">
          {['All', 'Active', 'Onboarding', 'Churned'].map(status => (
            <button
              key={status}
              onClick={() => setStatusFilter(status)}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${
                statusFilter === status
                  ? 'bg-violet-600 text-white shadow-sm'
                  : 'text-slate-400 hover:text-white hover:bg-white/5'
              }`}
            >
              {status} ({status === 'All' ? stats.total : stats[status.toLowerCase() as keyof typeof stats]})
            </button>
          ))}
        </div>
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
          <input
            type="text"
            placeholder="Search clients..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-[#12141f] border border-white/10 rounded-lg pl-10 pr-4 py-2.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-violet-500/50 transition-colors"
          />
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.length === 0 && (
          <div className="col-span-full py-12 text-center text-slate-500 bg-[#12141f] rounded-xl border border-white/5">
            No clients found.
          </div>
        )}
        {filtered.map(client => {
          const clientProjects = projects.filter(p => p.clientId === client.id);
          const activeProjects = clientProjects.filter(p => p.status === 'In Progress' || p.status === 'Assigned');
          
          return (
            <div key={client.id} className="bg-[#12141f] border border-white/5 rounded-xl p-5 hover:border-white/10 transition-colors group flex flex-col">
              <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-lg bg-violet-600/20 flex items-center justify-center text-violet-400 font-bold shrink-0">
                    {client.company.charAt(0)}
                  </div>
                  <div>
                    <h3 className="text-base font-semibold text-white group-hover:text-violet-400 transition-colors">{client.company}</h3>
                    <p className="text-xs text-slate-500">{client.clientId}</p>
                  </div>
                </div>
                <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium border ${
                  client.status === 'Active' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' :
                  client.status === 'Onboarding' ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' :
                  'bg-red-500/10 text-red-400 border-red-500/20'
                }`}>
                  {client.status}
                </span>
              </div>

              <div className="space-y-2 mb-6 flex-1">
                <div className="flex items-center justify-between text-sm">
                  <span className="text-slate-500 flex items-center gap-2"><Briefcase className="w-4 h-4" /> POC</span>
                  <span className="text-white">{client.firstName} {client.lastName}</span>
                </div>
                <div className="flex items-center justify-between text-sm">
                  <span className="text-slate-500 flex items-center gap-2"><IndianRupee className="w-4 h-4" /> Retainer</span>
                  <span className="text-emerald-400 font-medium">₹{client.monthlyRetainer.toLocaleString('en-IN')}/mo</span>
                </div>
                <div className="flex items-center justify-between text-sm">
                  <span className="text-slate-500 flex items-center gap-2"><Calendar className="w-4 h-4" /> Since</span>
                  <span className="text-white">{client.startDate}</span>
                </div>
              </div>

              <div className="pt-4 border-t border-white/5 flex items-center justify-between">
                <div className="text-xs text-slate-400">
                  <span className="text-white font-medium">{activeProjects.length}</span> Active Projects
                </div>
                <Link
                  href={`/crm/clients/${client.id}`}
                  className="text-xs font-medium text-violet-400 hover:text-violet-300 flex items-center gap-1"
                >
                  View Profile <Eye className="w-3 h-3" />
                </Link>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import Link from 'next/link';
import {
  Users, Building2, FolderKanban, FileText, CreditCard,
  Bell, TrendingUp, Clock, CheckCircle, AlertCircle,
  ArrowUpRight, UserCheck, Activity,
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';

// ── Helpers ──────────────────────────────────────────────────────────────────
const fmt = (n: number) =>
  n >= 100000
    ? `₹${(n / 100000).toFixed(1)}L`
    : n >= 1000
    ? `₹${(n / 1000).toFixed(0)}K`
    : `₹${n}`;

const StatCard = ({
  label, value, sub, icon: Icon, color, href,
}: {
  label: string; value: string | number; sub?: string;
  icon: React.ElementType; color: string; href?: string;
}) => {
  const inner = (
    <div className={`bg-[#12141f] border border-white/5 rounded-xl p-5 hover:border-white/10 transition-all group ${href ? 'cursor-pointer' : ''}`}>
      <div className="flex items-start justify-between mb-4">
        <div className={`w-10 h-10 rounded-lg ${color} flex items-center justify-center`}>
          <Icon className="w-5 h-5 text-white" />
        </div>
        {href && <ArrowUpRight className="w-4 h-4 text-slate-600 group-hover:text-slate-400 transition-colors" />}
      </div>
      <p className="text-2xl font-bold text-white mb-1">{value}</p>
      <p className="text-sm text-slate-500">{label}</p>
      {sub && <p className="text-xs text-slate-600 mt-1">{sub}</p>}
    </div>
  );
  return href ? <Link href={href}>{inner}</Link> : inner;
};

export default function CrmDashboardPage() {
  const { leads, clients, projects, employees, invoices, payments, notifications, getUnreadCount } = useCrmStore();
  const unread = getUnreadCount();

  const stats = useMemo(() => {
    const readyLeads = leads.filter(l => l.crmStatus === 'Pending Review');
    const activeClients = clients.filter(c => c.status === 'Active' || c.status === 'Onboarding');
    const activeProjects = projects.filter(p => p.status === 'In Progress' || p.status === 'Assigned');
    const pendingInvoices = invoices.filter(i => i.crmStatus === 'Sent' || i.crmStatus === 'Payment Pending' || i.crmStatus === 'Overdue');
    const overdueInvoices = invoices.filter(i => i.crmStatus === 'Overdue');
    const verifiedPayments = payments.filter(p => p.status === 'Paid');
    const totalRevenue = verifiedPayments.reduce((sum, p) => sum + p.amount, 0);
    const unassignedProjects = projects.filter(p => p.status === 'Waiting Assignment');
    const availableEmployees = employees.filter(e => e.availability === 'Available');
    const avgProgress = activeProjects.length
      ? Math.round(activeProjects.reduce((s, p) => s + p.progress, 0) / activeProjects.length)
      : 0;

    return {
      readyLeads: readyLeads.length,
      activeClients: activeClients.length,
      activeProjects: activeProjects.length,
      pendingInvoices: pendingInvoices.length,
      overdueInvoices: overdueInvoices.length,
      totalRevenue,
      unassignedProjects: unassignedProjects.length,
      availableEmployees: availableEmployees.length,
      avgProgress,
      totalClients: clients.length,
      totalProjects: projects.length,
    };
  }, [leads, clients, projects, employees, invoices, payments]);

  // Recent activity — last 5 notifications
  const recentActivity = notifications.slice(0, 6);

  // Top 5 active projects by progress
  const topProjects = projects
    .filter(p => p.status === 'In Progress')
    .sort((a, b) => b.progress - a.progress)
    .slice(0, 5);

  // Employees with high workload
  const busyEmployees = employees
    .sort((a, b) => b.workloadPercent - a.workloadPercent)
    .slice(0, 5);

  return (
    <div className="p-4 md:p-6 space-y-4 md:space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">CRM Dashboard</h1>
          <p className="text-slate-500 text-sm mt-0.5">Welcome back — here&apos;s your overview</p>
        </div>
        <div className="text-right">
          <p className="text-sm text-slate-400">
            {new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
          </p>
        </div>
      </div>

      {/* Alert Banner */}
      {(stats.overdueInvoices > 0 || stats.unassignedProjects > 0 || unread > 0) && (
        <div className="bg-amber-500/10 border border-amber-500/20 rounded-xl p-4 flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-amber-400 shrink-0 mt-0.5" />
          <div className="flex flex-wrap gap-4 text-sm">
            {stats.overdueInvoices > 0 && (
              <Link href="/crm/invoices" className="text-amber-300 hover:underline">
                {stats.overdueInvoices} overdue invoice{stats.overdueInvoices > 1 ? 's' : ''} →
              </Link>
            )}
            {stats.unassignedProjects > 0 && (
              <Link href="/crm/projects" className="text-amber-300 hover:underline">
                {stats.unassignedProjects} project{stats.unassignedProjects > 1 ? 's' : ''} need assignment →
              </Link>
            )}
            {unread > 0 && (
              <Link href="/crm/notifications" className="text-amber-300 hover:underline">
                {unread} unread notification{unread > 1 ? 's' : ''} →
              </Link>
            )}
          </div>
        </div>
      )}

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard label="Leads Pending" value={stats.readyLeads} sub="Pending Review" icon={Users} color="bg-violet-600" href="/crm/leads" />
        <StatCard label="Active Clients" value={`${stats.activeClients}/${stats.totalClients}`} sub="Active + Onboarding" icon={Building2} color="bg-emerald-600" href="/crm/clients" />
        <StatCard label="Active Projects" value={`${stats.activeProjects}/${stats.totalProjects}`} sub={`Avg ${stats.avgProgress}% progress`} icon={FolderKanban} color="bg-blue-600" href="/crm/projects" />
        <StatCard label="Total Revenue" value={fmt(stats.totalRevenue)} sub="Verified payments" icon={TrendingUp} color="bg-rose-600" href="/crm/payments" />
        <StatCard label="Pending Invoices" value={stats.pendingInvoices} sub={stats.overdueInvoices > 0 ? `${stats.overdueInvoices} overdue` : 'All on track'} icon={FileText} color="bg-amber-600" href="/crm/invoices" />
        <StatCard label="Unread Notifications" value={unread} sub="Action required" icon={Bell} color="bg-purple-600" href="/crm/notifications" />
        <StatCard label="Available Employees" value={stats.availableEmployees} sub={`of ${employees.length} total`} icon={UserCheck} color="bg-cyan-600" href="/crm/employees" />
        <StatCard label="Needs Assignment" value={stats.unassignedProjects} sub="Projects waiting" icon={Clock} color="bg-orange-600" href="/crm/projects" />
      </div>

      {/* Middle Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 md:gap-6">
        {/* Active Projects */}
        <div className="lg:col-span-2 bg-[#12141f] border border-white/5 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-semibold text-white">Top Active Projects</h2>
            <Link href="/crm/projects" className="text-xs text-violet-400 hover:text-violet-300 flex items-center gap-1">
              View all <ArrowUpRight className="w-3 h-3" />
            </Link>
          </div>
          <div className="space-y-3">
            {topProjects.map(p => (
              <Link key={p.id} href={`/crm/projects/${p.id}`}>
                <div className="flex items-center gap-3 p-3 rounded-lg hover:bg-white/5 transition-colors group">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-white truncate group-hover:text-violet-300 transition-colors">{p.name}</p>
                    <p className="text-xs text-slate-500 truncate">{p.company}</p>
                  </div>
                  <div className="flex items-center gap-3 shrink-0">
                    <div className="w-24 hidden sm:block">
                      <div className="h-1.5 bg-white/10 rounded-full overflow-hidden">
                        <div
                          className="h-full rounded-full bg-gradient-to-r from-violet-500 to-purple-500 transition-all"
                          style={{ width: `${p.progress}%` }}
                        />
                      </div>
                    </div>
                    <span className="text-xs font-semibold text-violet-400 w-8 text-right">{p.progress}%</span>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        </div>

        {/* Employee Workload */}
        <div className="bg-[#12141f] border border-white/5 rounded-xl p-5">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-semibold text-white">Employee Workload</h2>
            <Link href="/crm/employees" className="text-xs text-violet-400 hover:text-violet-300 flex items-center gap-1">
              All <ArrowUpRight className="w-3 h-3" />
            </Link>
          </div>
          <div className="space-y-3">
            {busyEmployees.map(emp => (
              <div key={emp.id} className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-violet-600/20 flex items-center justify-center text-xs font-bold text-violet-400 shrink-0">
                  {emp.name?.charAt(0)}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-medium text-white truncate">{emp.name}</p>
                  <div className="h-1 bg-white/10 rounded-full mt-1 overflow-hidden">
                    <div
                      className={`h-full rounded-full transition-all ${
                        emp.workloadPercent >= 80 ? 'bg-red-500' : emp.workloadPercent >= 60 ? 'bg-amber-500' : 'bg-emerald-500'
                      }`}
                      style={{ width: `${emp.workloadPercent}%` }}
                    />
                  </div>
                </div>
                <span className="text-xs font-semibold text-slate-400 w-9 text-right shrink-0">{emp.workloadPercent}%</span>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Recent Activity */}
      <div className="bg-[#12141f] border border-white/5 rounded-xl p-5">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold text-white flex items-center gap-2">
            <Activity className="w-4 h-4 text-violet-400" />
            Recent Activity
          </h2>
          <Link href="/crm/notifications" className="text-xs text-violet-400 hover:text-violet-300 flex items-center gap-1">
            View all <ArrowUpRight className="w-3 h-3" />
          </Link>
        </div>
        <div className="space-y-2">
          {recentActivity.map(n => (
            <div key={n.id} className={`flex items-start gap-3 p-3 rounded-lg transition-colors ${n.read ? 'opacity-60' : 'bg-violet-500/5 border border-violet-500/10'}`}>
              <div className={`w-2 h-2 rounded-full mt-1.5 shrink-0 ${n.read ? 'bg-slate-600' : 'bg-violet-500'}`} />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-white">{n.title}</p>
                <p className="text-xs text-slate-400 mt-0.5">{n.message}</p>
              </div>
              <div className="text-right shrink-0">
                <p className="text-[10px] text-slate-600">{n.date}</p>
                <p className="text-[10px] text-slate-600">{n.time}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Pipeline Status */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Invoice Sent', color: 'bg-blue-500', count: invoices.filter(i => i.crmStatus === 'Sent').length },
          { label: 'Payment Pending', color: 'bg-amber-500', count: invoices.filter(i => i.crmStatus === 'Payment Pending').length },
          { label: 'Advance Paid', color: 'bg-emerald-500', count: invoices.filter(i => i.crmStatus === 'Advance Paid').length },
          { label: 'Fully Paid', color: 'bg-violet-500', count: invoices.filter(i => i.crmStatus === 'Fully Paid').length },
        ].map(({ label, color, count }) => (
          <div key={label} className="bg-[#12141f] border border-white/5 rounded-xl p-4 flex items-center gap-3">
            <div className={`w-3 h-3 rounded-full ${color} shrink-0`} />
            <div>
              <p className="text-xl font-bold text-white">{count}</p>
              <p className="text-xs text-slate-500">{label}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import {
  Search, Users, Briefcase, Activity, Target
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';

export default function CrmEmployeesPage() {
  const { employees, projects } = useCrmStore();
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState<string>('All');

  const roles = ['All', ...Array.from(new Set(employees.map(e => e.role).filter(Boolean)))] as string[];

  const filtered = useMemo(() => {
    return employees
      .filter(e => {
        const q = search.toLowerCase();
        const matchSearch = !q || e.name?.toLowerCase().includes(q) || e.role?.toLowerCase().includes(q);
        const matchRole = roleFilter === 'All' || e.role === roleFilter;
        return matchSearch && matchRole;
      })
      .sort((a, b) => b.workloadPercent - a.workloadPercent);
  }, [employees, search, roleFilter]);

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Employees</h1>
          <p className="text-sm text-slate-500 mt-0.5">Manage team workload and assignments</p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col lg:flex-row gap-4">
        <div className="flex gap-2 bg-[#12141f] p-1 rounded-lg border border-white/5 overflow-x-auto scrollbar-hide">
          {roles.map(r => (
            <button
              key={r}
              onClick={() => setRoleFilter(r)}
              className={`shrink-0 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                roleFilter === r
                  ? 'bg-violet-600 text-white shadow-sm'
                  : 'text-slate-400 hover:text-white hover:bg-white/5'
              }`}
            >
              {r}
            </button>
          ))}
        </div>
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
          <input
            type="text"
            placeholder="Search employees..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-[#12141f] border border-white/10 rounded-lg pl-10 pr-4 py-2.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-violet-500/50 transition-colors"
          />
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.length === 0 && (
          <div className="col-span-full py-12 text-center text-slate-500 bg-[#12141f] rounded-xl border border-white/5">
            No employees found.
          </div>
        )}
        {filtered.map(emp => {
          const empProjects = emp.currentProjectIds.map(id => projects.find(p => p.id === id)).filter(Boolean);
          
          return (
            <div key={emp.id} className="bg-[#12141f] border border-white/5 rounded-xl p-5">
              <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-full bg-slate-800 border-2 border-[#12141f] flex items-center justify-center text-lg font-bold text-white">
                    {emp.name?.charAt(0)}
                  </div>
                  <div>
                    <h3 className="text-base font-semibold text-white">{emp.name}</h3>
                    <p className="text-xs text-slate-500">{emp.role}</p>
                  </div>
                </div>
                <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium border ${
                  emp.availability === 'Available' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' :
                  emp.availability === 'Busy' ? 'bg-red-500/10 text-red-400 border-red-500/20' :
                  'bg-amber-500/10 text-amber-400 border-amber-500/20'
                }`}>
                  {emp.availability}
                </span>
              </div>

              <div className="space-y-4">
                <div>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="text-slate-400 flex items-center gap-1"><Activity className="w-3 h-3" /> Workload</span>
                    <span className={`font-medium ${emp.workloadPercent >= 80 ? 'text-red-400' : 'text-emerald-400'}`}>
                      {emp.workloadPercent}%
                    </span>
                  </div>
                  <div className="h-1.5 bg-white/5 rounded-full overflow-hidden border border-white/5">
                    <div 
                      className={`h-full rounded-full transition-all ${
                        emp.workloadPercent >= 80 ? 'bg-red-500' : emp.workloadPercent >= 50 ? 'bg-amber-500' : 'bg-emerald-500'
                      }`}
                      style={{ width: `${emp.workloadPercent}%` }} 
                    />
                  </div>
                </div>

                <div className="pt-4 border-t border-white/5">
                  <div className="flex items-center justify-between mb-3">
                    <h4 className="text-xs font-semibold text-slate-400 flex items-center gap-1">
                      <Briefcase className="w-3 h-3" /> Active Projects ({empProjects.length})
                    </h4>
                  </div>
                  
                  <div className="space-y-2">
                    {empProjects.length === 0 ? (
                      <p className="text-xs text-slate-500 italic">No active projects</p>
                    ) : (
                      empProjects.slice(0, 3).map(p => (
                        <div key={p!.id} className="flex items-center justify-between text-xs p-2 bg-white/5 rounded-lg border border-white/5">
                          <span className="text-slate-300 truncate pr-2">{p!.name}</span>
                          <span className="text-violet-400 font-medium shrink-0">{p!.progress}%</span>
                        </div>
                      ))
                    )}
                    {empProjects.length > 3 && (
                      <p className="text-xs text-slate-500 text-center pt-1">+ {empProjects.length - 3} more</p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import {
  Search, FileText, IndianRupee, Clock, CheckCircle, 
  AlertCircle, Send, Plus
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';

const STATUS_COLORS: Record<string, string> = {
  'Draft': 'bg-slate-500/10 text-slate-400 border-slate-500/20',
  'Sent': 'bg-blue-500/10 text-blue-400 border-blue-500/20',
  'Payment Pending': 'bg-amber-500/10 text-amber-400 border-amber-500/20',
  'Advance Paid': 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
  'Fully Paid': 'bg-violet-500/10 text-violet-400 border-violet-500/20',
  'Overdue': 'bg-red-500/10 text-red-400 border-red-500/20',
};

export default function CrmInvoicesPage() {
  const { invoices, sendInvoiceReminder } = useCrmStore();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('All');

  const filtered = useMemo(() => {
    return invoices
      .filter(i => {
        const q = search.toLowerCase();
        const matchSearch = !q || i.invoiceNumber.toLowerCase().includes(q) || i.clientName.toLowerCase().includes(q);
        const matchStatus = statusFilter === 'All' || i.crmStatus === statusFilter;
        return matchSearch && matchStatus;
      })
      .sort((a, b) => new Date(b.issueDate).getTime() - new Date(a.issueDate).getTime());
  }, [invoices, search, statusFilter]);

  const stats = {
    total: invoices.reduce((s, i) => s + i.grandTotal, 0),
    paid: invoices.filter(i => i.crmStatus === 'Advance Paid' || i.crmStatus === 'Fully Paid').reduce((s, i) => s + i.grandTotal, 0),
    pending: invoices.filter(i => i.crmStatus === 'Sent' || i.crmStatus === 'Payment Pending').reduce((s, i) => s + i.grandTotal, 0),
    overdue: invoices.filter(i => i.crmStatus === 'Overdue').reduce((s, i) => s + i.grandTotal, 0),
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Invoices</h1>
          <p className="text-sm text-slate-500 mt-0.5">Track and manage client invoices</p>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-[#12141f] p-4 rounded-xl border border-white/5">
          <p className="text-slate-500 text-xs mb-1">Total Invoiced</p>
          <p className="text-xl font-bold text-white">₹{stats.total.toLocaleString('en-IN')}</p>
        </div>
        <div className="bg-[#12141f] p-4 rounded-xl border border-emerald-500/20">
          <p className="text-emerald-500/80 text-xs mb-1">Paid</p>
          <p className="text-xl font-bold text-emerald-400">₹{stats.paid.toLocaleString('en-IN')}</p>
        </div>
        <div className="bg-[#12141f] p-4 rounded-xl border border-amber-500/20">
          <p className="text-amber-500/80 text-xs mb-1">Pending</p>
          <p className="text-xl font-bold text-amber-400">₹{stats.pending.toLocaleString('en-IN')}</p>
        </div>
        <div className="bg-[#12141f] p-4 rounded-xl border border-red-500/20">
          <p className="text-red-500/80 text-xs mb-1">Overdue</p>
          <p className="text-xl font-bold text-red-400">₹{stats.overdue.toLocaleString('en-IN')}</p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col lg:flex-row gap-4">
        <div className="flex gap-2 bg-[#12141f] p-1 rounded-lg border border-white/5 overflow-x-auto scrollbar-hide">
          {['All', 'Draft', 'Sent', 'Payment Pending', 'Advance Paid', 'Fully Paid', 'Overdue'].map(status => (
            <button
              key={status}
              onClick={() => setStatusFilter(status)}
              className={`shrink-0 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                statusFilter === status
                  ? 'bg-violet-600 text-white shadow-sm'
                  : 'text-slate-400 hover:text-white hover:bg-white/5'
              }`}
            >
              {status}
            </button>
          ))}
        </div>
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
          <input
            type="text"
            placeholder="Search invoices..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-[#12141f] border border-white/10 rounded-lg pl-10 pr-4 py-2.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-violet-500/50 transition-colors"
          />
        </div>
      </div>

      {/* Table */}
      <div className="bg-[#12141f] border border-white/5 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-white/5 text-slate-500 text-xs uppercase tracking-wider">
                <th className="text-left px-5 py-3 font-medium">Invoice No</th>
                <th className="text-left px-5 py-3 font-medium">Client</th>
                <th className="text-right px-5 py-3 font-medium">Amount</th>
                <th className="text-left px-5 py-3 font-medium">Date</th>
                <th className="text-center px-5 py-3 font-medium">Status</th>
                <th className="text-right px-5 py-3 font-medium">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {filtered.length === 0 && (
                <tr><td colSpan={6} className="text-center py-12 text-slate-500">No invoices found</td></tr>
              )}
              {filtered.map(invoice => (
                <tr key={invoice.id} className="hover:bg-white/3 transition-colors group">
                  <td className="px-5 py-4">
                    <span className="font-medium text-white">{invoice.invoiceNumber}</span>
                  </td>
                  <td className="px-5 py-4">
                    <p className="font-semibold text-white">{invoice.clientName}</p>
                  </td>
                  <td className="px-5 py-4 text-right">
                    <span className="font-semibold text-emerald-400">₹{invoice.grandTotal.toLocaleString('en-IN')}</span>
                  </td>
                  <td className="px-5 py-4 text-slate-400 text-xs">
                    {invoice.issueDate}
                  </td>
                  <td className="px-5 py-4 text-center">
                    <span className={`text-[10px] px-2.5 py-1 rounded-full border font-medium ${STATUS_COLORS[invoice.crmStatus] || 'bg-white/5 text-slate-400 border-white/10'}`}>
                      {invoice.crmStatus}
                    </span>
                  </td>
                  <td className="px-5 py-4 text-right">
                    {invoice.crmStatus === 'Overdue' || invoice.crmStatus === 'Payment Pending' ? (
                      <button 
                        onClick={() => sendInvoiceReminder(invoice.id)}
                        disabled={invoice.reminderSent}
                        className={`inline-flex items-center gap-1 text-xs font-medium px-3 py-1.5 rounded transition-colors ${
                          invoice.reminderSent 
                            ? 'bg-white/5 text-slate-500 cursor-not-allowed' 
                            : 'bg-violet-500/10 text-violet-400 hover:bg-violet-500/20'
                        }`}
                      >
                        {invoice.reminderSent ? 'Reminder Sent' : 'Send Reminder'} <Send className="w-3 h-3" />
                      </button>
                    ) : (
                      <span className="text-xs text-slate-500">—</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="px-5 py-3 border-t border-white/5 text-xs text-slate-500">
          Showing {filtered.length} of {invoices.length} invoices
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Logo } from '@/components/ui/Logo';
import {
  LayoutDashboard, Users, FolderKanban, UserCheck,
  FileText, CreditCard, Bell, BarChart3, Settings,
  LogOut, Menu, X, ChevronRight, Briefcase,
  Building2, CheckCircle,
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';
import { useAuthStore } from '@/store/authStore';
import { authService } from '@/services/authService';
import { ProtectedRoute } from '@/components/auth/ProtectedRoute';

const navItems = [
  { href: '/crm/dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { href: '/crm/leads', label: 'Leads', icon: Users },
  { href: '/crm/clients', label: 'Clients', icon: Building2 },
  { href: '/crm/projects', label: 'Projects', icon: FolderKanban },
  { href: '/crm/employees', label: 'Employees', icon: UserCheck },
  { href: '/crm/invoices', label: 'Invoices', icon: FileText },
  { href: '/crm/payments', label: 'Payments', icon: CreditCard },
  { href: '/crm/notifications', label: 'Notifications', icon: Bell, badge: true },
  { href: '/crm/reports', label: 'Reports', icon: BarChart3 },
  { href: '/crm/settings', label: 'Settings', icon: Settings },
];

export default function CrmLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const getUnreadCount = useCrmStore(s => s.getUnreadCount);
  const fetchAllData = useCrmStore(s => s.fetchAllData);
  const unread = getUnreadCount();
  const { user, logout, refreshToken } = useAuthStore();

  useEffect(() => {
    fetchAllData();
  }, [fetchAllData]);

  const handleLogout = async () => {
    try {
      if (refreshToken) await authService.logout(refreshToken);
    } catch {
      // ignore — still clear local state
    } finally {
      logout();
    }
  };

  return (
    <ProtectedRoute allowedRoles={['admin', 'crm', 'finance']}>
    <div className="flex h-screen bg-[#0d0f17] overflow-hidden">
      {sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside
        className={`fixed lg:static inset-y-0 left-0 z-50 w-64 flex flex-col bg-[#12141f] border-r border-white/5 transform transition-transform duration-300 lg:translate-x-0 ${
          sidebarOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {/* Logo */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-white/5">
          <Logo size="sidebar" variant="white" href="/crm" />
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-slate-400 hover:text-white">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* User */}
        <div className="px-4 py-3 border-b border-white/5">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-violet-500 to-purple-600 flex items-center justify-center text-white text-xs font-bold shrink-0">
              {user?.name?.charAt(0) ?? 'C'}
            </div>
            <div className="min-w-0">
              <p className="text-white text-xs font-semibold truncate">{user?.name ?? 'CRM Admin'}</p>
              <p className="text-slate-500 text-[10px] truncate">{user?.email ?? 'crm@amplivo.in'}</p>
            </div>
          </div>
        </div>

        {/* Nav */}
        <nav className="flex-1 overflow-y-auto py-3 px-2 space-y-0.5">
          {navItems.map(({ href, label, icon: Icon, badge }) => {
            const active = pathname === href || (pathname.startsWith(href + '/') && href !== '/crm/dashboard');
            return (
              <Link
                key={href}
                href={href}
                onClick={() => setSidebarOpen(false)}
                className={`flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all group relative ${
                  active
                    ? 'bg-violet-600/20 text-violet-300 border border-violet-500/20'
                    : 'text-slate-400 hover:text-white hover:bg-white/5'
                }`}
              >
                <Icon className={`w-4 h-4 shrink-0 ${active ? 'text-violet-400' : 'text-slate-500 group-hover:text-slate-300'}`} />
                <span className="flex-1">{label}</span>
                {badge && unread > 0 && (
                  <span className="bg-violet-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full min-w-[18px] text-center leading-none">
                    {unread > 9 ? '9+' : unread}
                  </span>
                )}
                {active && <ChevronRight className="w-3 h-3 text-violet-500 shrink-0" />}
              </Link>
            );
          })}
        </nav>

        {/* Bottom */}
        <div className="p-3 border-t border-white/5 space-y-1">
          <Link
            href="/sales"
            className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-slate-400 hover:text-white hover:bg-white/5 transition-all group"
          >
            <CheckCircle className="w-4 h-4 text-emerald-500 group-hover:text-emerald-400" />
            <span>Sales Portal</span>
          </Link>
          <button
            onClick={handleLogout}
            className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-slate-400 hover:text-red-400 hover:bg-red-500/5 transition-all"
          >
            <LogOut className="w-4 h-4" />
            <span>Logout</span>
          </button>
        </div>
      </aside>

      {/* Main */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Topbar */}
        <header className="h-14 flex items-center justify-between px-4 border-b border-white/5 bg-[#12141f]/80 backdrop-blur-sm shrink-0">
          <div className="flex items-center gap-3">
            <button
              onClick={() => setSidebarOpen(true)}
              className="lg:hidden text-slate-400 hover:text-white transition-colors"
            >
              <Menu className="w-5 h-5" />
            </button>
            <div className="hidden sm:flex items-center gap-2 text-sm text-slate-500">
              <span className="text-slate-300">CRM</span>
              {pathname !== '/crm' && (
                <>
                  <ChevronRight className="w-3 h-3" />
                  <span className="text-violet-400 capitalize">
                    {pathname.split('/').slice(2).join(' / ').replace(/-/g, ' ')}
                  </span>
                </>
              )}
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Link href="/crm/notifications" className="relative p-2 text-slate-400 hover:text-white transition-colors">
              <Bell className="w-5 h-5" />
              {unread > 0 && (
                <span className="absolute top-1 right-1 w-2 h-2 bg-violet-500 rounded-full ring-2 ring-[#12141f]" />
              )}
            </Link>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto">
          {children}
        </main>
      </div>
    </div>
    </ProtectedRoute>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import {
  ArrowLeft, CheckCircle, Mail, Briefcase,
  FileText, Clock, AlertCircle, RefreshCw, UserCheck, Phone,
  Globe, MapPin, Tag, Download
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';
import { leadService } from '@/services/leadService';
import { financeService } from '@/services/crmService';

interface InvoiceRead {
  id: string;
  invoice_number: string;
  invoice_type: string;
  status: string;
  total_amount: number;
  currency: string;
  due_date: string;
}

interface PaymentRead {
  id: string;
