  payment_method: string;
  status: string;
  reference_number: string | null;
}

export default function CrmLeadDetailsPage() {
  const params = useParams();
  const router = useRouter();
  const { getLeadById, fetchLeads } = useCrmStore();

  const lead = getLeadById(params.id as string);
  const [reviewNotes, setReviewNotes] = useState(lead?.reviewNotes || '');
  const [rejectReason, setRejectReason] = useState('');
  const [showReject, setShowReject] = useState(false);

  const [invoice, setInvoice] = useState<InvoiceRead | null>(null);
  const [payments, setPayments] = useState<PaymentRead[]>([]);
  const [loadingInvoice, setLoadingInvoice] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);
  const [emailLive, setEmailLive] = useState(true);
  const [pdfLoading, setPdfLoading] = useState<'view' | 'download' | null>(null);
  const [resending, setResending] = useState(false);
  const [resendMessage, setResendMessage] = useState<string | null>(null);

  useEffect(() => {
    financeService.getEmailDeliveryStatus().then((r) => setEmailLive(r.live)).catch(() => setEmailLive(true));
  }, []);

  const loadInvoiceAndPayments = async (leadId: string) => {
    setLoadingInvoice(true);
    try {
      const inv = await financeService.getAdvanceInvoiceForLead(leadId);
      setInvoice(inv);
      if (inv) {
        const pays = await financeService.getPayments(inv.id);
        setPayments(pays || []);
      } else {
        setPayments([]);
      }
    } catch {
      setInvoice(null);
      setPayments([]);
    } finally {
      setLoadingInvoice(false);
    }
  };

  useEffect(() => {
    if (lead?.id) loadInvoiceAndPayments(lead.id);
     
  }, [lead?.id]);

  if (!lead) {
    return (
      <div className="p-6 text-center text-slate-400">
        <p>Lead not found.</p>
        <button onClick={() => router.push('/crm/leads')} className="mt-4 text-violet-400 hover:underline">
          Back to Leads
        </button>
      </div>
    );
  }

  const sl = lead.salesLead;

  // Real backend actions: CRM approving/rejecting the lead's advance
  // invoice/proposal - replacing the old local-only mock reviewLead/
  // sendInvoiceEmail/generateCredentials/convertLeadToClient actions, which
  // never reached the database and were disconnected from the real
  // Sales -> CRM -> Payments -> Client-account pipeline built on the backend.
  const handleApprove = async () => {
    if (!invoice) {
      setActionError('No advance invoice found for this lead yet - ask Sales to generate one first.');
      return;
    }
    setActionLoading(true);
    setActionError(null);
    try {
      if (reviewNotes.trim()) {
        await leadService.update(lead.id, { notes: reviewNotes }).catch(() => {});
      }
      await financeService.crmApproveInvoice(invoice.id);
      await Promise.all([fetchLeads(), loadInvoiceAndPayments(lead.id)]);
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Failed to approve. Please try again.');
    } finally {
      setActionLoading(false);
    }
  };

  const handleViewPdf = async () => {
    if (!invoice) return;
    setPdfLoading('view');
    try {
      const blob = await financeService.fetchInvoicePdfBlob(invoice.id);
      const url = URL.createObjectURL(blob);
      window.open(url, '_blank', 'noopener,noreferrer');
      setTimeout(() => URL.revokeObjectURL(url), 60_000);
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Failed to open the invoice PDF.');
    } finally {
      setPdfLoading(null);
    }
  };

  const handleDownloadPdf = async () => {
    if (!invoice) return;
    setPdfLoading('download');
    try {
      const blob = await financeService.fetchInvoicePdfBlob(invoice.id);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `invoice-${invoice.invoice_number}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Failed to download the invoice PDF.');
    } finally {
      setPdfLoading(null);
    }
  };

  const handleResendEmail = async () => {
    if (!invoice) return;
    setResending(true);
    setResendMessage(null);
    try {
      await financeService.resendInvoiceEmail(invoice.id);
      await loadInvoiceAndPayments(lead.id);
      setResendMessage('Payment-link email resent.');
    } catch (err) {
      setResendMessage(err instanceof Error ? err.message : 'Failed to resend the email.');
    } finally {
      setResending(false);
    }
  };

  const handleReject = async () => {
    setActionLoading(true);
    setActionError(null);
    try {
      await leadService.markLost(lead.id, rejectReason || undefined, 'REJECTED');
      await fetchLeads();
      setShowReject(false);
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Failed to reject. Please try again.');
    } finally {
      setActionLoading(false);
    }
  };

  const awaitingPayment = lead.crmStatus === 'Approved';
  const isClientCreated = lead.crmStatus === 'Client Created';

  return (
    <div className="p-6 max-w-5xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link href="/crm/leads" className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-slate-400 hover:text-white transition-colors">
            <ArrowLeft className="w-4 h-4" />
          </Link>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-white">{sl.firstName} {sl.lastName}</h1>
              <span className={`text-[10px] px-2.5 py-1 rounded-full border font-medium bg-white/5 border-white/10 text-white`}>
                {lead.crmStatus}
              </span>
            </div>
            <p className="text-sm text-slate-500 mt-0.5">{sl.company} · Received from Sales on {lead.receivedAt}</p>
          </div>
        </div>
      </div>

      {actionError && (
        <div className="p-3.5 bg-red-500/10 border border-red-500/20 rounded-lg text-sm text-red-300 flex items-center gap-2">
          <AlertCircle className="w-4 h-4 shrink-0" /> {actionError}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Col: Details */}
        <div className="lg:col-span-2 space-y-6">
          {/* Handover Notes */}
          <div className="bg-[#12141f] border border-white/5 rounded-xl p-5">
            <h2 className="text-sm font-semibold text-white flex items-center gap-2 mb-4">
              <Briefcase className="w-4 h-4 text-violet-400" />
              Sales Handover Details
            </h2>
            <div className="bg-violet-500/5 border border-violet-500/10 rounded-lg p-4 mb-5">
              <p className="text-sm text-slate-300 italic">&quot;{lead.salesLead.notes}&quot;</p>
              <div className="mt-3 flex items-center gap-2 text-xs text-slate-500">
                <span className="w-5 h-5 rounded-full bg-slate-800 flex items-center justify-center font-bold text-white">
                  {lead.salesLead.assignedTo.charAt(0)}
                </span>
                <span>{lead.salesLead.assignedTo} (Sales Executive)</span>
              </div>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
              <div>
                <p className="text-xs text-slate-500 mb-1">Company Size</p>
                <p className="text-sm font-medium text-white">{sl.companySize || '—'}</p>
              </div>
              <div>
                <p className="text-xs text-slate-500 mb-1">Industry</p>
                <p className="text-sm font-medium text-white">{sl.industry || '—'}</p>
              </div>
              <div>
                <p className="text-xs text-slate-500 mb-1">Approved Budget</p>
                <p className={`text-sm font-medium ${(sl.budget ?? 0) > 0 ? 'text-emerald-400' : 'text-amber-400'}`}>
                  ₹{(sl.budget ?? 0).toLocaleString('en-IN')}
                </p>
              </div>
            </div>
          </div>

          {/* Requested Services */}
          <div className="bg-[#12141f] border border-white/5 rounded-xl p-5">
            <h2 className="text-sm font-semibold text-white flex items-center gap-2 mb-4">
              <Tag className="w-4 h-4 text-violet-400" />
              Required Services
            </h2>
            <div className="flex flex-wrap gap-2">
              {sl.interestedServices.length === 0 ? (
                <p className="text-sm text-slate-500 italic">No services recorded on this lead.</p>
              ) : sl.interestedServices.map(s => (
                <span key={s} className="px-3 py-1.5 rounded-lg bg-white/5 border border-white/10 text-sm text-slate-300">
                  {s}
                </span>
              ))}
            </div>
          </div>

          {/* Contact Info */}
          <div className="bg-[#12141f] border border-white/5 rounded-xl p-5">
            <h2 className="text-sm font-semibold text-white mb-4">Contact Information</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="flex items-center gap-3 p-3 bg-white/5 rounded-lg">
                <Mail className="w-4 h-4 text-slate-400" />
                <div>
                  <p className="text-xs text-slate-500">Email</p>
                  <p className="text-sm text-white">{sl.email || '—'}</p>
                </div>
              </div>
              <div className="flex items-center gap-3 p-3 bg-white/5 rounded-lg">
                <Phone className="w-4 h-4 text-slate-400" />
                <div>
                  <p className="text-xs text-slate-500">Phone</p>
                  <p className="text-sm text-white">{sl.phone || '—'}</p>
                </div>
              </div>
              <div className="flex items-center gap-3 p-3 bg-white/5 rounded-lg">
                <Globe className="w-4 h-4 text-slate-400" />
                <div>
                  <p className="text-xs text-slate-500">Website</p>
                  <p className="text-sm text-white">{sl.website || '—'}</p>
                </div>
              </div>
              <div className="flex items-center gap-3 p-3 bg-white/5 rounded-lg">
                <MapPin className="w-4 h-4 text-slate-400" />
                <div>
                  <p className="text-xs text-slate-500">Location</p>
                  <p className="text-sm text-white">{sl.city || '—'}</p>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Right Col: CRM Actions & Workflow */}
        <div className="space-y-6">
          {/* CRM Workflow Engine */}
          <div className="bg-[#12141f] border border-white/5 rounded-xl p-5 shadow-xl shadow-black/20 relative overflow-hidden">
            <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-violet-500 to-fuchsia-500" />
            <h2 className="text-base font-bold text-white mb-5 flex items-center gap-2">
              <RefreshCw className="w-4 h-4 text-violet-400" />
              Onboarding Workflow
            </h2>

            <div className="space-y-6">
              {/* STEP 1: Review */}
              <div className="relative pl-6 border-l border-white/10 pb-2">
                <div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full border-4 border-[#12141f] ${lead.crmStatus === 'Pending Review' ? 'bg-violet-500' : 'bg-emerald-500'}`} />
                <h3 className="text-sm font-semibold text-white">1. Lead Review</h3>
                <p className="text-xs text-slate-500 mt-1">Review handover and verify scope, then approve to send the invoice + payment link.</p>

                {lead.crmStatus === 'Pending Review' && !showReject && (
                  <div className="mt-4 space-y-3">
                    {loadingInvoice ? (
                      <p className="text-xs text-slate-500">Loading invoice…</p>
                    ) : !invoice ? (
                      <p className="text-xs text-amber-400">No advance invoice found yet for this lead - Sales needs to generate one first.</p>
                    ) : null}
                    <textarea
                      placeholder="Add CRM review notes..."
                      value={reviewNotes}
                      onChange={e => setReviewNotes(e.target.value)}
                      className="w-full h-20 bg-white/5 border border-white/10 rounded-lg p-3 text-sm text-white focus:outline-none focus:border-violet-500/50 resize-none"
                    />
                    <div className="flex gap-2">
                      <button
                        onClick={handleApprove}
                        disabled={actionLoading || !invoice}
                        className="flex-1 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white text-sm font-medium py-2 rounded-lg transition-colors flex items-center justify-center gap-2"
                      >
                        <CheckCircle className="w-4 h-4" /> {actionLoading ? 'Approving…' : 'Approve'}
                      </button>
                      <button onClick={() => setShowReject(true)} disabled={actionLoading} className="px-4 bg-red-600/20 text-red-400 hover:bg-red-600/30 disabled:opacity-50 text-sm font-medium py-2 rounded-lg transition-colors">
                        Reject
                      </button>
                    </div>
                  </div>
                )}

                {showReject && (
                  <div className="mt-4 space-y-3">
                    <input
                      type="text"
                      placeholder="Reason for rejection..."
                      value={rejectReason}
                      onChange={e => setRejectReason(e.target.value)}
                      className="w-full bg-white/5 border border-red-500/30 rounded-lg p-2.5 text-sm text-white focus:outline-none focus:border-red-500"
                    />
                    <div className="flex gap-2">
                      <button onClick={handleReject} disabled={actionLoading} className="flex-1 bg-red-600 hover:bg-red-500 disabled:opacity-50 text-white text-sm font-medium py-2 rounded-lg transition-colors">
                        {actionLoading ? 'Rejecting…' : 'Confirm Reject'}
                      </button>
                      <button onClick={() => setShowReject(false)} disabled={actionLoading} className="px-4 bg-white/5 text-slate-400 hover:bg-white/10 disabled:opacity-50 text-sm font-medium py-2 rounded-lg transition-colors">
                        Cancel
                      </button>
                    </div>
                  </div>
                )}

                {lead.crmStatus === 'Rejected' && (
                  <div className="mt-3 p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-sm text-red-300">
                    This lead was rejected/marked lost.
                  </div>
                )}
              </div>

              {/* STEP 2: Invoice + payment-link email (automatic on approval) */}
              <div className="relative pl-6 border-l border-white/10 pb-2">
                <div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full border-4 border-[#12141f] ${
                  lead.crmStatus === 'Pending Review' ? 'bg-slate-700' : 'bg-emerald-500'
                }`} />
                <h3 className="text-sm font-semibold text-white">2. Invoice &amp; Payment Link</h3>
                <p className="text-xs text-slate-500 mt-1">Sent to the client automatically the moment CRM approves.</p>

                {invoice && (
                  <div className="mt-3 space-y-2">
                    <div className="flex items-center justify-between p-3 bg-white/5 rounded-lg border border-white/10">
                      <div className="flex items-center gap-2">
                        <FileText className="w-4 h-4 text-slate-400" />
                        <span className="text-sm text-slate-300">{invoice.invoice_number}</span>
                      </div>
                      <span className="text-sm font-semibold text-white">{invoice.currency} {invoice.total_amount.toLocaleString('en-IN')}</span>
                    </div>

                    {invoice.status === 'EMAIL_SENT' && !emailLive && (
                      <div className="p-2.5 bg-amber-500/10 border border-amber-500/20 rounded-lg text-xs text-amber-300 flex items-start gap-2">
                        <AlertCircle className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
                        <span>Email delivery is not configured (BREVO_API_KEY missing) — the client did not actually receive this email.</span>
                      </div>
                    )}

                    <div className="flex items-center justify-between px-1">
                      <span className="text-[10px] px-2 py-0.5 rounded-full border border-white/10 bg-white/5 text-slate-300 font-medium">
                        {invoice.status}
                      </span>
                      <div className="flex items-center gap-3">
                        <button
                          type="button"
                          onClick={handleResendEmail}
                          disabled={resending}
                          className="text-xs text-violet-400 hover:text-violet-300 disabled:opacity-50 flex items-center gap-1"
                        >
                          <RefreshCw className="w-3 h-3" /> {resending ? 'Resending…' : 'Resend Email'}
                        </button>
                        <button
                          type="button"
                          onClick={handleViewPdf}
                          disabled={pdfLoading !== null}
                          className="text-xs text-violet-400 hover:text-violet-300 disabled:opacity-50 flex items-center gap-1"
                        >
                          <FileText className="w-3 h-3" /> {pdfLoading === 'view' ? 'Opening…' : 'View PDF'}
                        </button>
                        <button
                          type="button"
                          onClick={handleDownloadPdf}
                          disabled={pdfLoading !== null}
                          className="text-xs text-violet-400 hover:text-violet-300 disabled:opacity-50 flex items-center gap-1"
                        >
                          <Download className="w-3 h-3" /> {pdfLoading === 'download' ? 'Downloading…' : 'Download'}
                        </button>
                      </div>
                    </div>
                    {resendMessage && <p className="text-[11px] text-slate-400 px-1">{resendMessage}</p>}
                  </div>
                )}
              </div>

              {/* STEP 3: Payment Tracking */}
              <div className="relative pl-6 border-l border-white/10 pb-2">
                <div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full border-4 border-[#12141f] ${
                  awaitingPayment ? 'bg-violet-500' : isClientCreated ? 'bg-emerald-500' : 'bg-slate-700'
                }`} />
                <h3 className="text-sm font-semibold text-white">3. Payment Verification</h3>
                <p className="text-xs text-slate-500 mt-1">Wait for client payment, then verify from the Payments tab.</p>

                {payments.length > 0 && (
                  <div className="mt-3 space-y-2">
                    {payments.map(p => (
                      <div key={p.id} className="flex items-center justify-between p-2.5 bg-white/5 rounded-lg border border-white/10 text-xs">
                        <span className="text-slate-300">{p.payment_method}{p.reference_number ? ` · ${p.reference_number}` : ''}</span>
                        <span className="text-white font-semibold">₹{p.amount.toLocaleString('en-IN')}</span>
                        <span className="text-slate-400">{p.status}</span>
                      </div>
                    ))}
                  </div>
                )}

                {awaitingPayment && (
                  <div className="mt-4 p-3 bg-amber-500/10 border border-amber-500/20 rounded-lg flex items-start gap-3">
                    <Clock className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
                    <p className="text-xs text-amber-300">
                      Awaiting payment. Check <Link href="/crm/payments" className="underline font-semibold">Payments tab</Link> to verify when received.
                    </p>
                  </div>
                )}
              </div>

              {/* STEP 4: Credentials (automatic once payment is CRM-verified) */}
              <div className="relative pl-6 border-l border-white/10 pb-2">
                <div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full border-4 border-[#12141f] ${isClientCreated ? 'bg-emerald-500' : 'bg-slate-700'}`} />
                <h3 className="text-sm font-semibold text-white">4. Client Credentials</h3>
                <p className="text-xs text-slate-500 mt-1">Portal login is generated and emailed automatically once payment is verified.</p>

                {isClientCreated && (
                  <div className="mt-3 p-3 bg-white/5 rounded-lg border border-white/10">
                    <p className="text-[11px] text-emerald-400 flex items-center gap-1">
                      <CheckCircle className="w-3 h-3" /> Credentials emailed to client
                    </p>
                  </div>
                )}
              </div>

              {/* STEP 5: Convert */}
              <div className="relative pl-6">
                <div className={`absolute -left-[9px] top-0 w-4 h-4 rounded-full border-4 border-[#12141f] ${isClientCreated ? 'bg-emerald-500' : 'bg-slate-700'}`} />
                <h3 className="text-sm font-semibold text-white">5. Convert to Client</h3>
                <p className="text-xs text-slate-500 mt-1">Client account + onboarding project are created automatically once payment is verified.</p>

                {isClientCreated && (
                  <div className="mt-4 text-center p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
                    <UserCheck className="w-8 h-8 text-emerald-400 mx-auto mb-2" />
                    <p className="text-sm font-semibold text-emerald-400">Successfully Onboarded</p>
                    {lead.convertedToClientId && (
                      <Link href={`/crm/clients/${lead.convertedToClientId}`} className="text-xs text-white hover:underline mt-1 block">
                        View Client Profile →
                      </Link>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import Link from 'next/link';
import {
  Search, Filter, ChevronDown, Eye, CheckCircle, XCircle,
  Clock, ArrowUpRight, Users, Building2, Phone, Mail,
  Calendar, IndianRupee, Tag,
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';
import { CrmLead, CrmLeadStatus } from '@/types/crm';

const STATUS_COLORS: Record<string, string> = {
  'Pending Review': 'bg-blue-500/20 text-blue-300 border-blue-500/30',
  'Approved': 'bg-emerald-500/20 text-emerald-300 border-emerald-500/30',
  'Rejected': 'bg-red-500/20 text-red-300 border-red-500/30',
  'Invoice Sent': 'bg-purple-500/20 text-purple-300 border-purple-500/30',
  'Payment Pending': 'bg-orange-500/20 text-orange-300 border-orange-500/30',
  'Payment Verified': 'bg-teal-500/20 text-teal-300 border-teal-500/30',
  'Credentials Sent': 'bg-cyan-500/20 text-cyan-300 border-cyan-500/30',
  'Client Created': 'bg-green-500/20 text-green-300 border-green-500/30',
  'Overdue': 'bg-red-500/20 text-red-300 border-red-500/30',
};

const STATUSES: CrmLeadStatus[] = [
  'Pending Review', 'Approved', 'Rejected',
  'Invoice Sent', 'Credentials Sent', 'Payment Pending', 'Payment Verified', 'Client Created'
];

export default function CrmLeadsPage() {
  const { leads, updateLeadStatus } = useCrmStore();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('All');
  const [sortBy, setSortBy] = useState<'date' | 'budget' | 'name'>('date');

  const filtered = useMemo(() => {
    return leads
      .filter(l => {
        const q = search.toLowerCase();
        const matchSearch = !q ||
          l.salesLead.firstName.toLowerCase().includes(q) ||
          l.salesLead.lastName.toLowerCase().includes(q) ||
          l.salesLead.company.toLowerCase().includes(q) ||
          l.salesLead.email.toLowerCase().includes(q);
        const matchStatus = statusFilter === 'All' || l.crmStatus === statusFilter;
        return matchSearch && matchStatus;
      })
      .sort((a, b) => {
        if (sortBy === 'budget') return (b.salesLead.budget ?? 0) - (a.salesLead.budget ?? 0);
        if (sortBy === 'name') return a.salesLead.firstName.localeCompare(b.salesLead.firstName);
        return new Date(b.receivedAt).getTime() - new Date(a.receivedAt).getTime();
      });
  }, [leads, search, statusFilter, sortBy]);

  const counts = useMemo(() => {
    return STATUSES.reduce((acc, s) => ({ ...acc, [s]: leads.filter(l => l.crmStatus === s).length }), {} as Record<string, number>);
  }, [leads]);

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">Leads Pipeline</h1>
          <p className="text-sm text-slate-500 mt-0.5">{leads.length} total leads · {leads.filter(l => l.crmStatus === 'Pending Review').length} pending review</p>
        </div>
      </div>

      {/* Status Tabs */}
      <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
        <button
          onClick={() => setStatusFilter('All')}
          className={`shrink-0 px-4 py-2 rounded-lg text-sm font-medium transition-all ${statusFilter === 'All' ? 'bg-violet-600 text-white' : 'bg-[#12141f] text-slate-400 hover:text-white border border-white/5'}`}
        >
          All ({leads.length})
        </button>
        {STATUSES.map(s => (
          <button
            key={s}
            onClick={() => setStatusFilter(s)}
            className={`shrink-0 px-4 py-2 rounded-lg text-sm font-medium transition-all ${statusFilter === s ? 'bg-violet-600 text-white' : 'bg-[#12141f] text-slate-400 hover:text-white border border-white/5'}`}
          >
            {s} ({counts[s] ?? 0})
          </button>
        ))}
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
          <input
            type="text"
            placeholder="Search leads..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-[#12141f] border border-white/10 rounded-lg pl-10 pr-4 py-2.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-violet-500/50 transition-colors"
          />
        </div>
        <select
          value={sortBy}
          onChange={e => setSortBy(e.target.value as typeof sortBy)}
          className="bg-[#12141f] border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white focus:outline-none focus:border-violet-500/50"
        >
          <option value="date">Sort: Newest</option>
          <option value="budget">Sort: Budget</option>
          <option value="name">Sort: Name</option>
        </select>
      </div>

      {/* Table */}
      <div className="bg-[#12141f] border border-white/5 rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-white/5 text-slate-500 text-xs uppercase tracking-wider">
                <th className="text-left px-5 py-3 font-medium">Lead</th>
                <th className="text-left px-5 py-3 font-medium hidden md:table-cell">Services</th>
                <th className="text-right px-5 py-3 font-medium hidden sm:table-cell">Budget</th>
                <th className="text-center px-5 py-3 font-medium">Status</th>
                <th className="text-right px-5 py-3 font-medium">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {filtered.length === 0 && (
                <tr><td colSpan={5} className="text-center py-12 text-slate-500">No leads found</td></tr>
              )}
              {filtered.map(lead => {
                const sl = lead.salesLead;
                return (
                  <tr key={lead.id} className="hover:bg-white/3 transition-colors group">
                    <td className="px-5 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-9 h-9 rounded-full bg-violet-600/20 flex items-center justify-center text-sm font-bold text-violet-400 shrink-0">
                          {sl.firstName.charAt(0)}
                        </div>
                        <div>
                          <p className="font-semibold text-white">{sl.firstName} {sl.lastName}</p>
                          <p className="text-xs text-slate-500">{sl.company} · {sl.city}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-5 py-4 hidden md:table-cell">
                      <div className="flex flex-wrap gap-1 max-w-xs">
                        {sl.interestedServices.slice(0, 2).map(s => (
                          <span key={s} className="text-[10px] px-2 py-0.5 bg-white/5 border border-white/10 rounded-full text-slate-400">{s.split(' ')[0]}</span>
                        ))}
                        {sl.interestedServices.length > 2 && (
                          <span className="text-[10px] px-2 py-0.5 bg-white/5 border border-white/10 rounded-full text-slate-500">+{sl.interestedServices.length - 2}</span>
                        )}
                      </div>
                    </td>
                    <td className="px-5 py-4 text-right hidden sm:table-cell">
                      <span className="font-semibold text-white">₹{((sl.budget ?? 0) / 1000).toFixed(0)}K</span>
                    </td>
                    <td className="px-5 py-4 text-center">
                      <span className={`text-[10px] px-2.5 py-1 rounded-full border font-medium ${STATUS_COLORS[lead.crmStatus] ?? 'bg-white/5 text-slate-400 border-white/10'}`}>
                        {lead.crmStatus}
                      </span>
                    </td>
                    <td className="px-5 py-4 text-right">
                      <Link
                        href={`/crm/leads/${lead.id}`}
                        className="inline-flex items-center gap-1 text-xs text-violet-400 hover:text-violet-300 font-medium transition-colors"
                      >
                        View <Eye className="w-3 h-3" />
                      </Link>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <div className="px-5 py-3 border-t border-white/5 text-xs text-slate-500">
          Showing {filtered.length} of {leads.length} leads
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import {
  ArrowLeft, FolderKanban, CheckCircle, Clock, Calendar,
  Building2, Users, Target, UserPlus
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';

export default function CrmProjectDetailsPage() {
  const params = useParams();
  const router = useRouter();
  const { 
    getProjectById, getClientById, employees, 
    completeMilestone, updateProjectProgress, updateProjectStatus,
    assignEmployeesToProject
  } = useCrmStore();
  
  const project = getProjectById(params.id as string);
  const client = project ? getClientById(project.clientId) : null;
  
  const [showAssign, setShowAssign] = useState(false);
  const [selectedEmps, setSelectedEmps] = useState<string[]>(project?.assignedEmployeeIds || []);

  if (!project) {
    return (
      <div className="p-6 text-center text-slate-400">
        <p>Project not found.</p>
        <button onClick={() => router.push('/crm/projects')} className="mt-4 text-violet-400 hover:underline">
          Back to Projects
        </button>
      </div>
    );
  }

  const handleSaveAssign = () => {
    assignEmployeesToProject(project.id, selectedEmps);
    setShowAssign(false);
  };

  const handleCompleteMilestone = (mId: string) => {
    completeMilestone(project.id, mId);
    
    // Auto-update progress based on milestones
    const updated = getProjectById(project.id);
    if (updated) {
      const completed = updated.milestones.filter(m => m.completed).length;
      const total = updated.milestones.length;
      const newProg = total > 0 ? Math.round((completed / total) * 100) : 0;
      updateProjectProgress(project.id, newProg);
      
      if (newProg === 100) {
        updateProjectStatus(project.id, 'Completed');
      } else if (newProg > 0 && updated.status !== 'In Progress') {
        updateProjectStatus(project.id, 'In Progress');
      }
    }
  };

  const assignedEmpsFull = employees.filter(e => project.assignedEmployeeIds.includes(e.id));

  return (
    <div className="p-6 max-w-6xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center gap-4">
        <Link href="/crm/projects" className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-slate-400 hover:text-white transition-colors">
          <ArrowLeft className="w-4 h-4" />
        </Link>
        <div className="flex-1">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-2xl font-bold text-white">{project.name}</h1>
                <span className={`text-[10px] px-2.5 py-1 rounded-full border font-medium ${
                  project.status === 'Completed' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' :
                  project.status === 'Waiting Assignment' ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' :
                  'bg-blue-500/10 text-blue-400 border-blue-500/20'
                }`}>
                  {project.status}
                </span>
              </div>
              <p className="text-sm text-slate-500 mt-0.5">
                {project.company} · {project.services.join(', ')}
              </p>
            </div>
            
            <div className="flex items-center gap-4">
              <div className="text-right">
                <p className="text-xs text-slate-500">Progress</p>
                <p className="text-lg font-bold text-violet-400">{project.progress}%</p>
              </div>
              <div className="w-32 h-2 bg-white/5 rounded-full overflow-hidden border border-white/5">
                <div 
                  className={`h-full rounded-full transition-all ${project.status === 'Completed' ? 'bg-emerald-500' : 'bg-gradient-to-r from-violet-500 to-purple-500'}`}
                  style={{ width: `${project.progress}%` }} 
                />
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Col: Details & Team */}
        <div className="space-y-6">
          {/* Info */}
          <div className="bg-[#12141f] border border-white/5 rounded-xl p-5 space-y-4">
            {client && (
              <div className="flex items-center gap-3">
                <Building2 className="w-4 h-4 text-slate-500" />
                <div>
                  <p className="text-xs text-slate-500">Client</p>
                  <Link href={`/crm/clients/${client.id}`} className="text-sm font-medium text-white hover:text-violet-400 transition-colors">
                    {client.company}
                  </Link>
                </div>
              </div>
            )}
            <div className="flex items-center gap-3">
              <Calendar className="w-4 h-4 text-slate-500" />
              <div>
                <p className="text-xs text-slate-500">Start Date</p>
                <p className="text-sm font-medium text-white">{project.startDate}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <Clock className="w-4 h-4 text-slate-500" />
              <div>
                <p className="text-xs text-slate-500">Deadline</p>
                <p className="text-sm font-medium text-white">{project.endDate}</p>
              </div>
            </div>
          </div>

          {/* Team */}
          <div className="bg-[#12141f] border border-white/5 rounded-xl p-5">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-sm font-semibold text-white flex items-center gap-2">
                <Users className="w-4 h-4 text-violet-400" />
                Project Team
              </h2>
              <button onClick={() => setShowAssign(!showAssign)} className="text-xs text-violet-400 hover:text-violet-300 flex items-center gap-1">
                <UserPlus className="w-3 h-3" /> Assign
              </button>
            </div>
            
            {showAssign ? (
              <div className="space-y-3 mb-4">
                <div className="h-48 overflow-y-auto pr-2 space-y-1">
                  {employees.map(emp => (
                    <label key={emp.id} className="flex items-center gap-3 p-2 rounded hover:bg-white/5 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={selectedEmps.includes(emp.id)}
                        onChange={(e) => {
                          if (e.target.checked) setSelectedEmps([...selectedEmps, emp.id]);
                          else setSelectedEmps(selectedEmps.filter(id => id !== emp.id));
                        }}
                        className="rounded border-white/20 bg-white/5 text-violet-500 focus:ring-violet-500/20"
                      />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm text-white truncate">{emp.name}</p>
                        <p className="text-[10px] text-slate-500 truncate">{emp.role}</p>
                      </div>
                      <div className="shrink-0 text-right">
                        <p className={`text-[10px] ${emp.workloadPercent >= 80 ? 'text-red-400' : 'text-emerald-400'}`}>
                          {emp.workloadPercent}% load
                        </p>
                      </div>
                    </label>
                  ))}
                </div>
                <div className="flex gap-2">
                  <button onClick={handleSaveAssign} className="flex-1 bg-violet-600 hover:bg-violet-500 text-white text-xs font-medium py-2 rounded transition-colors">
                    Save Team
                  </button>
                  <button onClick={() => setShowAssign(false)} className="px-3 bg-white/5 text-slate-400 hover:bg-white/10 text-xs font-medium py-2 rounded transition-colors">
                    Cancel
                  </button>
                </div>
              </div>
            ) : (
              <div className="space-y-3">
                {assignedEmpsFull.map(emp => (
                  <div key={emp.id} className="flex items-center gap-3 p-2 bg-white/5 rounded-lg border border-white/5">
                    <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center text-xs font-bold text-white">
                      {emp.name?.charAt(0)}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-white">{emp.name}</p>
                      <p className="text-[10px] text-slate-500">{emp.role}</p>
                    </div>
                  </div>
                ))}
                {assignedEmpsFull.length === 0 && (
                  <div className="text-center py-4 bg-amber-500/10 border border-amber-500/20 rounded-lg text-amber-400 text-sm">
                    No employees assigned.<br/>Click assign to add team members.
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Right Col: Milestones */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-[#12141f] border border-white/5 rounded-xl p-5">
            <h2 className="text-base font-semibold text-white mb-6 flex items-center gap-2">
              <Target className="w-5 h-5 text-violet-400" />
              Project Milestones
            </h2>
            
            <div className="space-y-0">
              {project.milestones.map((m, idx) => (
                <div key={m.id} className="relative flex gap-4 pb-6 last:pb-0 group">
                  {idx !== project.milestones.length - 1 && (
                    <div className={`absolute left-[11px] top-6 bottom-0 w-0.5 ${m.completed ? 'bg-violet-500' : 'bg-white/10'}`} />
                  )}
                  <div className="shrink-0 mt-1 relative z-10">
                    {m.completed ? (
                      <CheckCircle className="w-6 h-6 text-violet-500 bg-[#12141f] rounded-full" />
                    ) : (
                      <div className="w-6 h-6 rounded-full border-2 border-white/20 bg-[#12141f]" />
                    )}
                  </div>
                  <div className={`flex-1 p-4 rounded-xl border transition-colors ${
                    m.completed ? 'bg-violet-500/5 border-violet-500/20' : 'bg-white/5 border-white/5 hover:border-white/10'
                  }`}>
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                      <div>
                        <h3 className={`font-semibold ${m.completed ? 'text-violet-300' : 'text-white'}`}>{m.title}</h3>
                        <p className="text-sm text-slate-500 mt-1">Due: {m.dueDate}</p>
                      </div>
                      {!m.completed && (
                        <button 
                          onClick={() => handleCompleteMilestone(m.id)}
                          className="shrink-0 px-4 py-2 bg-white/5 hover:bg-white/10 text-white text-xs font-medium rounded-lg transition-colors border border-white/10"
                        >
                          Mark Complete
                        </button>
                      )}
                      {m.completed && m.completedAt && (
                        <div className="shrink-0 text-right">
                          <p className="text-xs text-emerald-400 flex items-center gap-1">
                            <CheckCircle className="w-3 h-3" /> Completed
                          </p>
                          <p className="text-[10px] text-slate-500 mt-0.5">{m.completedAt}</p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
              
              {project.milestones.length === 0 && (
                <p className="text-sm text-slate-500 text-center py-6">No milestones defined for this project.</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import Link from 'next/link';
import {
  Search, FolderKanban, Clock, CheckCircle,
  Eye, UserPlus, Calendar, AlertCircle
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';

export default function CrmProjectsPage() {
  const { projects, employees, clients } = useCrmStore();
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('All');

  const filtered = useMemo(() => {
    return projects
      .filter(p => {
        const q = search.toLowerCase();
        const matchSearch = !q ||
          p.name.toLowerCase().includes(q) ||
          p.company.toLowerCase().includes(q) ||
          p.services.join(', ').toLowerCase().includes(q);
        const matchStatus = statusFilter === 'All' || p.status === statusFilter;
        return matchSearch && matchStatus;
      })
      .sort((a, b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime());
  }, [projects, search, statusFilter]);

  const stats = {
    total: projects.length,
    active: projects.filter(p => p.status === 'In Progress').length,
    waiting: projects.filter(p => p.status === 'Waiting Assignment').length,
    completed: projects.filter(p => p.status === 'Completed').length,
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Projects</h1>
          <p className="text-sm text-slate-500 mt-0.5">Manage deliverables and team assignments</p>
        </div>
      </div>

      {/* Stats/Filters */}
      <div className="flex flex-col lg:flex-row gap-4">
        <div className="flex gap-2 bg-[#12141f] p-1 rounded-lg border border-white/5 overflow-x-auto scrollbar-hide">
          {['All', 'Waiting Assignment', 'Assigned', 'In Progress', 'Completed'].map(status => (
            <button
              key={status}
              onClick={() => setStatusFilter(status)}
              className={`shrink-0 px-4 py-2 rounded-md text-sm font-medium transition-all ${
                statusFilter === status
                  ? 'bg-violet-600 text-white shadow-sm'
                  : 'text-slate-400 hover:text-white hover:bg-white/5'
              }`}
            >
              {status}
            </button>
          ))}
        </div>
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
          <input
            type="text"
            placeholder="Search projects..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-[#12141f] border border-white/10 rounded-lg pl-10 pr-4 py-2.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-violet-500/50 transition-colors"
          />
        </div>
      </div>

      {/* List */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.length === 0 && (
          <div className="col-span-full py-12 text-center text-slate-500 bg-[#12141f] rounded-xl border border-white/5">
            No projects found.
          </div>
        )}
        {filtered.map(project => {
          const client = clients.find(c => c.id === project.clientId);
          
          return (
            <div key={project.id} className="bg-[#12141f] border border-white/5 rounded-xl p-5 hover:border-white/10 transition-colors group flex flex-col">
              <div className="flex justify-between items-start mb-4">
                <div className="flex-1 min-w-0 pr-4">
                  <h3 className="text-base font-semibold text-white group-hover:text-violet-400 transition-colors truncate">
                    {project.name}
                  </h3>
                  <p className="text-xs text-slate-500 truncate mt-0.5">{project.company}</p>
                </div>
                <span className={`shrink-0 text-[10px] px-2 py-0.5 rounded-full font-medium border ${
                  project.status === 'Completed' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' :
                  project.status === 'Waiting Assignment' ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' :
                  'bg-blue-500/10 text-blue-400 border-blue-500/20'
                }`}>
                  {project.status}
                </span>
              </div>

              <div className="flex-1 space-y-4">
                <div>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="text-slate-400">Progress</span>
                    <span className="text-white font-medium">{project.progress}%</span>
                  </div>
                  <div className="h-1.5 bg-white/5 rounded-full overflow-hidden border border-white/5">
                    <div 
                      className={`h-full rounded-full transition-all ${project.status === 'Completed' ? 'bg-emerald-500' : 'bg-gradient-to-r from-violet-500 to-purple-500'}`}
                      style={{ width: `${project.progress}%` }} 
                    />
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex -space-x-2">
                    {project.assignedEmployeeIds.length === 0 ? (
                      <div className="w-8 h-8 rounded-full border border-dashed border-white/20 flex items-center justify-center bg-white/5 text-slate-500">
                        <UserPlus className="w-3 h-3" />
                      </div>
                    ) : (
                      <>
                        {project.assignedEmployeeIds.slice(0, 4).map((id, i) => (
                          <div key={i} className="w-8 h-8 rounded-full bg-slate-800 border-2 border-[#12141f] flex items-center justify-center text-xs font-bold text-white relative z-10 hover:z-20 hover:scale-110 transition-transform cursor-pointer" title={employees.find(e => e.id === id)?.name}>
                            {employees.find(e => e.id === id)?.name?.charAt(0) || 'U'}
                          </div>
                        ))}
                        {project.assignedEmployeeIds.length > 4 && (
                          <div className="w-8 h-8 rounded-full bg-white/10 border-2 border-[#12141f] flex items-center justify-center text-[10px] font-bold text-slate-300 relative z-10">
                            +{project.assignedEmployeeIds.length - 4}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                  
                  <div className="text-right">
                    <p className="text-[10px] text-slate-500">Deadline</p>
                    <p className="text-xs font-medium text-white">{project.endDate}</p>
                  </div>
                </div>
              </div>

              <div className="mt-5 pt-4 border-t border-white/5 flex items-center justify-between">
                <span className="text-xs px-2 py-1 bg-white/5 rounded text-slate-400">
                  {project.services.join(', ')}
                </span>
                <Link
                  href={`/crm/projects/${project.id}`}
                  className="text-xs font-medium text-violet-400 hover:text-violet-300 flex items-center gap-1"
                >
                  Manage <Eye className="w-3 h-3" />
                </Link>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import {
  BarChart3, TrendingUp, Users, Building2, IndianRupee,
  Calendar, PieChart, Activity
} from 'lucide-react';
import { useCrmStore } from '@/store/crmStore';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  LineChart, Line, PieChart as RePieChart, Pie, Cell
} from 'recharts';

interface TooltipProps {
  active?: boolean;
  payload?: { name: string; value: number; color: string }[];
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: TooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-[#12141f] border border-white/10 p-3 rounded-lg shadow-xl">
        <p className="text-white font-medium mb-1">{label}</p>
        {payload.map((p, i) => (
          <p key={i} className="text-sm" style={{ color: p.color }}>
            {p.name}: {p.value.toLocaleString('en-IN')}
          </p>
        ))}
      </div>
    );
  }
  return null;
};

export default function CrmReportsPage() {
  const { leads, clients, payments, projects } = useCrmStore();

  // Real last-6-months revenue, aggregated from actually-verified payments
  // (status === 'Paid') by month - this used to be 5 hardcoded fake numbers
  // with only the current month backed by real data.
  const verifiedPayments = payments.filter(p => p.status === 'Paid');
  const revenueData = Array.from({ length: 6 }, (_, i) => {
    const d = new Date();
    d.setMonth(d.getMonth() - (5 - i));
    const monthKey = `${d.getFullYear()}-${d.getMonth()}`;
    const actual = verifiedPayments
      .filter(p => {
        const pd = new Date(p.date);
        return `${pd.getFullYear()}-${pd.getMonth()}` === monthKey;
      })
      .reduce((s, p) => s + p.amount, 0);
    return { name: d.toLocaleDateString('en-IN', { month: 'short' }), actual, projected: actual };
  });
  const lastMonthRevenue = revenueData[5].actual;
  const prevMonthRevenue = revenueData[4].actual;
  const revenueDeltaPct = prevMonthRevenue > 0
    ? Math.round(((lastMonthRevenue - prevMonthRevenue) / prevMonthRevenue) * 100)
    : (lastMonthRevenue > 0 ? 100 : 0);

  // Lead Conversion Funnel
  const funnelData = [
    { stage: 'Total Leads Received', value: leads.length },
    { stage: 'Pending Review', value: leads.filter(l => l.crmStatus === 'Pending Review').length },
    { stage: 'Approved', value: leads.filter(l => l.crmStatus !== 'Pending Review' && l.crmStatus !== 'Rejected').length },
    { stage: 'Converted to Client', value: clients.length },
  ];

  // Services Distribution
  const servicesMap: Record<string, number> = {};
  clients.forEach(c => c.services.forEach(s => {
    servicesMap[s] = (servicesMap[s] || 0) + 1;
  }));
  const servicesData = Object.entries(servicesMap).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value).slice(0, 5);
  const COLORS = ['#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ec4899'];

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-white">Reports & Analytics</h1>
        <p className="text-sm text-slate-500 mt-0.5">Key performance indicators and business metrics</p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-[#12141f] p-5 rounded-xl border border-white/5">
