'use client';
import { useEffect, useMemo, useState } from 'react';
import { ArrowUpRight, Search, Activity, Download, Loader2, Link2, ArrowUp, ArrowDown } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { seoService } from '@/services/moduleServices';
import { useToastStore } from '@/store/toastStore';

interface SeoProject { id: string; name: string; target_url: string; status: string }
interface SeoKeyword { id: string; keyword: string; current_rank: number | null; target_rank: number | null; search_volume: number | null; difficulty: number | null }
interface SeoAudit { id: string; audit_date: string; health_score: number | null; errors_count: number | null; warnings_count: number | null }
interface SeoBacklink { id: string; source_url: string; domain_authority: number | null; status: string }

type SortKey = 'keyword' | 'current_rank' | 'search_volume';

export default function SEOPage() {
  const [projects, setProjects] = useState<SeoProject[]>([]);
  const [keywords, setKeywords] = useState<SeoKeyword[]>([]);
  const [audits, setAudits] = useState<SeoAudit[]>([]);
  const [backlinks, setBacklinks] = useState<SeoBacklink[]>([]);
  const [loading, setLoading] = useState(true);
  const [fetchingReport, setFetchingReport] = useState(false);
  const [error, setError] = useState(false);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [sortKey, setSortKey] = useState<SortKey>('current_rank');
  const [sortAsc, setSortAsc] = useState(true);
  const [visibleCount, setVisibleCount] = useState(10);
  const [exporting, setExporting] = useState(false);
  const showToast = useToastStore((s) => s.showToast);

  const load = () => {
    setLoading(true);
    setError(false);
    seoService
      .getProjects({ page_size: 100 })
      .then((res) => {
        const items: SeoProject[] = res?.items ?? res ?? [];
        setProjects(items);
        if (items.length > 0) setSelectedProjectId(items[0].id);
      })
      .catch(() => setError(true))
      .finally(() => setLoading(false));
  };

  useEffect(load, []);

  useEffect(() => {
    if (!selectedProjectId) return;
    setVisibleCount(10);
    setFetchingReport(true);
    Promise.all([
      seoService.getKeywords(selectedProjectId).catch(() => []),
      seoService.getAudits(selectedProjectId).catch(() => []),
      seoService.getBacklinks(selectedProjectId).catch(() => []),
    ])
      .then(([kw, au, bl]) => {
        setKeywords(kw?.items ?? kw ?? []);
        setAudits((au?.items ?? au ?? []).sort((a: SeoAudit, b: SeoAudit) => new Date(a.audit_date).getTime() - new Date(b.audit_date).getTime()));
        setBacklinks(bl?.items ?? bl ?? []);
      })
      .finally(() => {
        setFetchingReport(false);
      });
  }, [selectedProjectId]);

  const totalKeywords = keywords.length;
  const ranked = keywords.filter((k) => k.current_rank != null);
  const avgPosition = ranked.length > 0 ? (ranked.reduce((sum, k) => sum + (k.current_rank || 0), 0) / ranked.length).toFixed(1) : '-';
  const latestHealth = audits.length > 0 ? audits[audits.length - 1].health_score : null;
  const activeBacklinks = backlinks.filter((b) => b.status === 'active').length;

  const healthTrend = audits.map((a) => ({ date: new Date(a.audit_date).toLocaleDateString('en-IN', { month: 'short', day: 'numeric' }), score: a.health_score ?? 0 }));

  const sortedKeywords = useMemo(() => {
    const copy = [...keywords];
    copy.sort((a, b) => {
      let av: number | string = 0;
      let bv: number | string = 0;
      if (sortKey === 'keyword') { av = a.keyword; bv = b.keyword; }
      else if (sortKey === 'current_rank') { av = a.current_rank ?? 9999; bv = b.current_rank ?? 9999; }
      else { av = a.search_volume ?? 0; bv = b.search_volume ?? 0; }
      if (av < bv) return sortAsc ? -1 : 1;
      if (av > bv) return sortAsc ? 1 : -1;
      return 0;
    });
    return copy;
  }, [keywords, sortKey, sortAsc]);

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) setSortAsc((a) => !a);
    else {
      setSortKey(key);
      setSortAsc(true);
    }
  };

  const handleExport = () => {
    setExporting(true);
    try {
      const project = projects.find((p) => p.id === selectedProjectId);
      const header = ['Keyword', 'Current Rank', 'Target Rank', 'Search Volume', 'Difficulty'];
      const rows = keywords.map((k) => [k.keyword, k.current_rank ?? '', k.target_rank ?? '', k.search_volume ?? '', k.difficulty ?? '']);
      const csv = [header, ...rows].map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `seo-report-${project?.name ?? 'project'}-${new Date().toISOString().slice(0, 10)}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      showToast('SEO report exported.', 'success');
    } finally {
      setExporting(false);
    }
  };

  if (loading) {
    return (
      <div className="p-8">
        <div className="flex items-center justify-center h-[60vh]">
          <Loader2 size={32} className="animate-spin text-[#4C1D95]" />
        </div>
      </div>
    );
  }

  return (
    <div className="p-8">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-bold text-slate-900" style={{ fontFamily: "'Sora', sans-serif" }}>SEO Performance</h1>
          <p className="text-slate-500 text-sm mt-1">Track keyword rankings, backlinks, and technical health.</p>
        </div>

        {projects.length > 0 && (
          <div className="flex items-center gap-3">
            {fetchingReport && <Loader2 size={16} className="animate-spin text-[#4C1D95]" />}
            <select
              className="bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg text-sm font-medium focus:outline-none focus:border-[#4C1D95] disabled:opacity-50"
              value={selectedProjectId || ''}
              disabled={fetchingReport}
              onChange={(e) => setSelectedProjectId(e.target.value)}
            >
              {projects.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
            <button onClick={handleExport} disabled={exporting || fetchingReport || keywords.length === 0} className="flex items-center gap-2 bg-[#4C1D95] text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-[#3b1574] transition-colors disabled:opacity-60">
              {exporting ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />} Export Report
            </button>
          </div>
        )}
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 text-sm rounded-xl p-4 mb-6">
          Couldn&apos;t load SEO data. <button onClick={load} className="underline font-medium">Retry</button>
        </div>
      )}

      {projects.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200 text-center py-16 text-sm text-slate-400">No SEO projects found</div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-semibold text-slate-500">Health Score</h3>
                <div className="w-8 h-8 rounded-full bg-[#10B981]/10 flex items-center justify-center text-[#10B981]"><Activity size={16} /></div>
              </div>
              <div className="text-3xl font-bold text-slate-900 mb-2">{latestHealth != null ? `${latestHealth}%` : '-'}</div>
              <div className="text-sm text-slate-400">{audits.length > 0 ? `Last audit ${new Date(audits[audits.length - 1].audit_date).toLocaleDateString()}` : 'No audits yet'}</div>
            </div>

            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-semibold text-slate-500">Total Keywords</h3>
                <div className="w-8 h-8 rounded-full bg-[#4C1D95]/10 flex items-center justify-center text-[#4C1D95]"><Search size={16} /></div>
              </div>
              <div className="text-3xl font-bold text-slate-900 mb-2">{totalKeywords}</div>
              <div className="flex items-center gap-1 text-sm text-slate-400"><span>Tracked keywords</span></div>
            </div>

            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-semibold text-slate-500">Avg. Position</h3>
                <div className="w-8 h-8 rounded-full bg-[#F59E0B]/10 flex items-center justify-center text-[#F59E0B]"><ArrowUpRight size={16} /></div>
              </div>
              <div className="text-3xl font-bold text-slate-900 mb-2">{avgPosition}</div>
              <div className="text-sm text-slate-400">Average across ranked keywords</div>
            </div>

            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-semibold text-slate-500">Active Backlinks</h3>
                <div className="w-8 h-8 rounded-full bg-[#06B6D4]/10 flex items-center justify-center text-[#06B6D4]"><Link2 size={16} /></div>
              </div>
              <div className="text-3xl font-bold text-slate-900 mb-2">{activeBacklinks}</div>
              <div className="text-sm text-slate-400">{backlinks.length} total backlinks</div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <h3 className="text-lg font-bold text-slate-900 mb-6" style={{ fontFamily: "'Sora', sans-serif" }}>Site Health Over Time</h3>
              <div className="h-[300px] w-full">
                {healthTrend.length === 0 ? (
                  <div className="h-full flex items-center justify-center text-sm text-slate-400">No audits recorded yet for this project</div>
                ) : (
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={healthTrend} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E2E8F0" />
                      <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{ fill: '#64748B', fontSize: 12 }} dy={10} />
                      <YAxis axisLine={false} tickLine={false} tick={{ fill: '#64748B', fontSize: 12 }} dx={-10} domain={[0, 100]} />
                      <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                      <Line type="monotone" dataKey="score" stroke="#4C1D95" strokeWidth={3} dot={{ r: 4, fill: '#4C1D95' }} />
                    </LineChart>
                  </ResponsiveContainer>
                )}
              </div>
            </div>

            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm overflow-hidden flex flex-col">
              <h3 className="text-lg font-bold text-slate-900 mb-4" style={{ fontFamily: "'Sora', sans-serif" }}>Keywords</h3>
              <div className="flex-1 overflow-auto">
                {keywords.length === 0 ? (
                  <div className="text-center py-8 text-sm text-slate-400">No keywords tracked yet</div>
                ) : (
                  <>
                    <table className="w-full text-left border-collapse">
                      <thead>
                        <tr className="border-b border-slate-100">
                          <th className="pb-3 text-xs font-semibold text-slate-500 cursor-pointer select-none" onClick={() => toggleSort('keyword')}>
                            Keyword {sortKey === 'keyword' && (sortAsc ? <ArrowUp size={10} className="inline" /> : <ArrowDown size={10} className="inline" />)}
                          </th>
                          <th className="pb-3 text-xs font-semibold text-slate-500 text-right cursor-pointer select-none" onClick={() => toggleSort('current_rank')}>
                            Rank {sortKey === 'current_rank' && (sortAsc ? <ArrowUp size={10} className="inline" /> : <ArrowDown size={10} className="inline" />)}
                          </th>
                          <th className="pb-3 text-xs font-semibold text-slate-500 text-right cursor-pointer select-none" onClick={() => toggleSort('search_volume')}>
                            Vol {sortKey === 'search_volume' && (sortAsc ? <ArrowUp size={10} className="inline" /> : <ArrowDown size={10} className="inline" />)}
                          </th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {sortedKeywords.slice(0, visibleCount).map((kw) => (
                          <tr key={kw.id}>
                            <td className="py-3">
                              <div className="text-sm font-medium text-slate-900 truncate max-w-[150px]">{kw.keyword}</div>
                            </td>
                            <td className="py-3 text-right">
                              <span className="text-sm font-bold text-slate-900">{kw.current_rank ?? '-'}</span>
                              {kw.target_rank != null && <span className="text-[10px] text-slate-400 ml-1">/ {kw.target_rank}</span>}
                            </td>
                            <td className="py-3 text-right text-sm text-slate-600 font-medium">{kw.search_volume ?? '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {visibleCount < sortedKeywords.length && (
                      <button onClick={() => setVisibleCount((c) => c + 10)} className="w-full text-center text-xs text-[#4C1D95] font-medium py-3 hover:underline">
                        Show more ({sortedKeywords.length - visibleCount} remaining)
                      </button>
                    )}
                  </>
                )}
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

'use client';
export const dynamic = 'force-dynamic';
import { useEffect, useRef, useState } from 'react';
import { User as UserIcon, Building2, Bell, Shield, Check, Loader2, Eye, EyeOff } from 'lucide-react';
import { useAuthStore } from '@/store/authStore';
import { useToastStore } from '@/store/toastStore';
import { useRouter } from 'next/navigation';
import { settingsService } from '@/services/moduleServices';
import { userManagementService } from '@/services/crmService';
import { fileManagerService } from '@/services/moduleServices';
import { companyService, ClientRead } from '@/services/portalServices';
import { authService } from '@/services/authService';
import { PhoneInput } from '@/components/ui/PhoneInput';

type Tab = 'profile' | 'company' | 'notifications' | 'security';

const API_ORIGIN = (process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000/api/v1').replace(/\/api\/v1\/?$/, '');
const resolveUrl = (url: string) => (url.startsWith('http') ? url : `${API_ORIGIN}${url}`);

export default function SettingsPage() {
  const { user, logout, token, refreshToken, login } = useAuthStore();
  const router = useRouter();
  const showToast = useToastStore((s) => s.showToast);
  const [tab, setTab] = useState<Tab>('profile');
  const [loading, setLoading] = useState(true);

  // Profile state
  const [fullName, setFullName] = useState(user?.name ?? '');
  const [phone, setPhone] = useState('');
  const [avatarUrl, setAvatarUrl] = useState<string | null>(user?.image ?? null);
  const [savingProfile, setSavingProfile] = useState(false);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);
  const avatarInputRef = useRef<HTMLInputElement>(null);

  // BUG-017: Track original profile values to detect dirty state
  const [originalFullName, setOriginalFullName] = useState(user?.name ?? '');
  const [originalPhone, setOriginalPhone] = useState('');
  const isProfileDirty = fullName !== originalFullName || phone !== originalPhone;

  // Company state
  const [company, setCompany] = useState<ClientRead | null>(null);
  const [companyForm, setCompanyForm] = useState({ display_name: '', website: '', phone: '' });
  const [originalCompanyForm, setOriginalCompanyForm] = useState({ display_name: '', website: '', phone: '' });
  const [savingCompany, setSavingCompany] = useState(false);
  const isCompanyDirty = JSON.stringify(companyForm) !== JSON.stringify(originalCompanyForm);

  // Notifications preferences
  const [preferences, setPreferences] = useState<{ theme: string; email_notifications: boolean; in_app_notifications: boolean } | null>(null);
  const [originalPreferences, setOriginalPreferences] = useState<{ theme: string; email_notifications: boolean; in_app_notifications: boolean } | null>(null);
  const [savingPrefs, setSavingPrefs] = useState(false);
  // BUG-017: Only enable save prefs if preferences have changed
  const isPreferencesDirty = preferences && originalPreferences
    ? JSON.stringify(preferences) !== JSON.stringify(originalPreferences)
    : false;

  // Security
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [changingPassword, setChangingPassword] = useState(false);
  const [passwordError, setPasswordError] = useState('');
  // BUG-015: Password visibility toggles
  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  useEffect(() => {
    if (!user?.id) return;
    setLoading(true);
    Promise.all([
      userManagementService.getUser(user.id).catch(() => null),
      userManagementService.getUserProfile(user.id).catch(() => null),
      settingsService.getMyPreferences().catch(() => null),
      companyService.getMine().catch(() => null),
    ]).then(([detail, profile, prefs, myCompany]) => {
      const loadedName = detail?.full_name ?? user?.name ?? '';
      const loadedPhone = detail?.phone ?? '';
      if (detail?.phone) setPhone(loadedPhone);
      if (detail?.full_name) setFullName(loadedName);
      // BUG-017: set original values for dirty detection
      setOriginalFullName(loadedName);
      setOriginalPhone(loadedPhone);

      if (profile?.avatar_url) setAvatarUrl(profile.avatar_url);

      const defaultPrefs = { theme: 'light', email_notifications: true, in_app_notifications: true };
      const resolvedPrefs = prefs ?? defaultPrefs;
      setPreferences(resolvedPrefs);
      setOriginalPreferences(resolvedPrefs);

      if (myCompany) {
        setCompany(myCompany);
        const compForm = { display_name: myCompany.display_name ?? '', website: myCompany.website ?? '', phone: myCompany.phone ?? '' };
        setCompanyForm(compForm);
        setOriginalCompanyForm(compForm);
      }
      setLoading(false);
    });
  }, [user?.id]);

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setSavingProfile(true);
    try {
      await userManagementService.updateUser(user.id, { full_name: fullName.trim(), phone: phone.trim() });
      login({ ...user, name: fullName.trim() }, token ?? '', refreshToken ?? undefined);
      setOriginalFullName(fullName.trim());
      setOriginalPhone(phone.trim());
      showToast('Profile updated successfully.', 'success');
    } catch {
      showToast('Failed to update profile.', 'error');
    } finally {
      setSavingProfile(false);
    }
  };

  const handleAvatarChange = async (fileList: FileList | null) => {
    if (!fileList || fileList.length === 0 || !user) return;
    setUploadingAvatar(true);
    try {
      const uploaded = await fileManagerService.uploadBinary(fileList[0]);
      const url = resolveUrl(uploaded.url);
      await userManagementService.upsertUserProfile(user.id, { full_name: fullName.trim() || user.name, avatar_url: url });
      setAvatarUrl(url);
      // BUG-018: Update auth store so sidebar/header Avatar re-renders with new image
      login({ ...user, image: url }, token ?? '', refreshToken ?? undefined);
      showToast('Avatar updated.', 'success');
    } catch {
      showToast('Failed to upload avatar.', 'error');
    } finally {
      setUploadingAvatar(false);
      if (avatarInputRef.current) avatarInputRef.current.value = '';
    }
  };

  const handleSaveCompany = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!company) return;
    setSavingCompany(true);
    try {
      const updated = await companyService.update(company.id, companyForm);
      setCompany(updated);
      setOriginalCompanyForm({ ...companyForm });
      showToast('Company details updated.', 'success');
    } catch {
      showToast('Failed to update company details.', 'error');
    } finally {
      setSavingCompany(false);
    }
  };

  const handleSavePreferences = async () => {
    if (!preferences) return;
    setSavingPrefs(true);
    try {
      await settingsService.updateMyPreferences(preferences);
      setOriginalPreferences({ ...preferences });
      showToast('Notification preferences saved.', 'success');
    } catch {
      showToast('Failed to save preferences.', 'error');
    } finally {
      setSavingPrefs(false);
    }
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setPasswordError('');
    if (newPassword !== confirmPassword) {
      setPasswordError('New passwords do not match.');
      return;
    }
    if (newPassword.length < 8) {
      setPasswordError('New password must be at least 8 characters.');
      return;
    }
    setChangingPassword(true);
    try {
      await authService.changePassword(currentPassword, newPassword);
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
      showToast('Password changed successfully.', 'success');
    } catch (err: unknown) {
      const message = (err as { response?: { data?: { message?: string } } })?.response?.data?.message || 'Failed to change password.';
      setPasswordError(message);
    } finally {
      setChangingPassword(false);
    }
  };

  if (loading) {
    return (
      <div className="p-8 max-w-5xl mx-auto">
        <div className="flex items-center justify-center h-[60vh]">
          <Loader2 size={32} className="animate-spin text-[#4C1D95]" />
        </div>
      </div>
    );
  }

  // BUG-016: Removed 'Sign out' from the tab navigation — it already exists in the sidebar
  const navButtons: { key: Tab; label: string; icon: typeof UserIcon }[] = [
    { key: 'profile', label: 'Profile', icon: UserIcon },
    { key: 'company', label: 'Company details', icon: Building2 },
    { key: 'notifications', label: 'Notifications', icon: Bell },
    { key: 'security', label: 'Password & Security', icon: Shield },
  ];

  return (
    <div className="p-8 max-w-5xl mx-auto">
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-slate-900" style={{ fontFamily: "'Sora', sans-serif" }}>Account Settings</h1>
        <p className="text-slate-500 text-sm mt-1">Manage your profile, company details, and preferences.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
        {/* BUG-016: No Sign Out button here — only navigation tabs */}
        <div className="md:col-span-1 space-y-1">
          {navButtons.map(({ key, label, icon: Icon }) => (
            <button
              key={key}
              onClick={() => setTab(key)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-medium text-sm transition-colors ${
                tab === key ? 'bg-[#4C1D95]/10 text-[#4C1D95] font-semibold' : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              <Icon size={18} /> {label}
            </button>
          ))}
        </div>

        <div className="md:col-span-3 space-y-6">
          {tab === 'profile' && (
            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <h2 className="text-lg font-bold text-slate-900 mb-6" style={{ fontFamily: "'Sora', sans-serif" }}>Profile Information</h2>

              <div className="flex items-center gap-6 mb-8">
                <div className="w-20 h-20 rounded-full overflow-hidden border border-slate-200 bg-slate-100 flex items-center justify-center">
                  {avatarUrl ? <img src={avatarUrl} alt={user?.name} className="w-full h-full object-cover" /> : <UserIcon size={28} className="text-slate-400" />}
                </div>
                <div>
                  <input ref={avatarInputRef} type="file" accept="image/*" className="hidden" onChange={(e) => handleAvatarChange(e.target.files)} />
                  <button
                    type="button"
                    onClick={() => avatarInputRef.current?.click()}
                    disabled={uploadingAvatar}
                    className="bg-white border border-slate-200 text-slate-700 px-4 py-2 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors mb-2 disabled:opacity-60 flex items-center gap-2"
                  >
                    {uploadingAvatar && <Loader2 size={14} className="animate-spin" />}
                    {uploadingAvatar ? 'Uploading...' : 'Change avatar'}
                  </button>
                  <p className="text-xs text-slate-500">JPG, GIF or PNG. 20MB max.</p>
                </div>
              </div>

              <form className="space-y-4" onSubmit={handleSaveProfile}>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1.5">Full Name <span className="text-red-500">*</span></label>
                  <input type="text" required pattern="[A-Za-z\s]+" title="Only letters and spaces are allowed" minLength={2} value={fullName} onChange={(e) => setFullName(e.target.value)} className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 focus:border-[#4C1D95]" />
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1.5">Email Address</label>
                  <input type="email" value={user?.email || ''} disabled className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm text-slate-500" />
                  <p className="text-xs text-slate-500 mt-1.5">Contact your account manager to change your email address.</p>
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1.5">Phone Number</label>
                  <PhoneInput value={phone} onChange={(val) => setPhone(val || '')} />
                </div>

                <div className="pt-4 border-t border-slate-100 flex justify-end">
                  {/* BUG-017: Disabled when form is pristine */}
                  <button
                    type="submit"
                    disabled={savingProfile || !isProfileDirty}
                    title={!isProfileDirty ? 'No changes to save' : undefined}
                    className="flex items-center gap-2 bg-[#4C1D95] text-white px-6 py-2.5 rounded-xl text-sm font-semibold hover:bg-[#3b1574] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {savingProfile ? <Loader2 size={16} className="animate-spin" /> : <Check size={16} />}
                    {savingProfile ? 'Saving...' : 'Save Changes'}
                  </button>
                </div>
              </form>
            </div>
          )}

          {tab === 'company' && (
            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <h2 className="text-lg font-bold text-slate-900 mb-6" style={{ fontFamily: "'Sora', sans-serif" }}>Company Details</h2>
              {!company ? (
                <p className="text-sm text-slate-400">No company information linked to this account.</p>
              ) : (
                <form className="space-y-4" onSubmit={handleSaveCompany}>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1.5">Company Name</label>
                      <input type="text" value={company.company_name} disabled className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm text-slate-500" />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1.5">Industry</label>
                      <input type="text" value={company.industry ?? '-'} disabled className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm text-slate-500" />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1.5">Display Name</label>
                    <input type="text" value={companyForm.display_name} onChange={(e) => setCompanyForm((p) => ({ ...p, display_name: e.target.value }))} className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 focus:border-[#4C1D95]" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1.5">Website</label>
                      <input type="url" value={companyForm.website} onChange={(e) => setCompanyForm((p) => ({ ...p, website: e.target.value }))} className="w-full border border-slate-200 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 focus:border-[#4C1D95]" />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1.5">Phone</label>
                      <PhoneInput value={companyForm.phone} onChange={(val) => setCompanyForm((p) => ({ ...p, phone: val || '' }))} />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1.5">GST Number</label>
                      <input type="text" value={company.gst_number ?? '-'} disabled className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm text-slate-500" />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1.5">PAN Number</label>
                      <input type="text" value={company.pan_number ?? '-'} disabled className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm text-slate-500" />
                    </div>
                  </div>
                  <p className="text-xs text-slate-500">Tax/registration details can only be updated by your account manager.</p>
                  <div className="pt-4 border-t border-slate-100 flex justify-end">
                    {/* BUG-017: Disabled when company form is pristine */}
                    <button
                      type="submit"
                      disabled={savingCompany || !isCompanyDirty}
                      title={!isCompanyDirty ? 'No changes to save' : undefined}
                      className="flex items-center gap-2 bg-[#4C1D95] text-white px-6 py-2.5 rounded-xl text-sm font-semibold hover:bg-[#3b1574] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {savingCompany ? <Loader2 size={16} className="animate-spin" /> : <Check size={16} />}
                      {savingCompany ? 'Saving...' : 'Save Changes'}
                    </button>
                  </div>
                </form>
              )}
            </div>
          )}

          {tab === 'notifications' && preferences && (
            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <h2 className="text-lg font-bold text-slate-900 mb-6" style={{ fontFamily: "'Sora', sans-serif" }}>Notification Preferences</h2>
              <div className="space-y-4">
                <label className="flex items-center justify-between p-4 rounded-xl border border-slate-200">
                  <div>
                    <p className="text-sm font-medium text-slate-900">Email notifications</p>
                    <p className="text-xs text-slate-500">Receive updates about campaigns, invoices, and messages by email.</p>
                  </div>
                  <input
                    type="checkbox"
                    checked={preferences.email_notifications}
                    onChange={(e) => setPreferences((p) => (p ? { ...p, email_notifications: e.target.checked } : p))}
                    className="w-5 h-5 accent-[#4C1D95]"
                  />
                </label>
                <label className="flex items-center justify-between p-4 rounded-xl border border-slate-200">
                  <div>
                    <p className="text-sm font-medium text-slate-900">In-app notifications</p>
                    <p className="text-xs text-slate-500">Show notifications in the bell icon while you&apos;re using the portal.</p>
                  </div>
                  <input
                    type="checkbox"
                    checked={preferences.in_app_notifications}
                    onChange={(e) => setPreferences((p) => (p ? { ...p, in_app_notifications: e.target.checked } : p))}
                    className="w-5 h-5 accent-[#4C1D95]"
                  />
                </label>
              </div>
              <div className="pt-6 mt-2 border-t border-slate-100 flex justify-end">
                {/* BUG-017: Disabled when preferences are pristine */}
                <button
                  onClick={handleSavePreferences}
                  disabled={savingPrefs || !isPreferencesDirty}
                  title={!isPreferencesDirty ? 'No changes to save' : undefined}
                  className="flex items-center gap-2 bg-[#4C1D95] text-white px-6 py-2.5 rounded-xl text-sm font-semibold hover:bg-[#3b1574] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {savingPrefs ? <Loader2 size={16} className="animate-spin" /> : <Check size={16} />}
                  {savingPrefs ? 'Saving...' : 'Save Preferences'}
                </button>
              </div>
            </div>
          )}

          {tab === 'security' && (
            <div className="bg-white rounded-2xl p-6 border border-slate-200 shadow-sm">
              <h2 className="text-lg font-bold text-slate-900 mb-6" style={{ fontFamily: "'Sora', sans-serif" }}>Password & Security</h2>
              <form className="space-y-4 max-w-md" onSubmit={handleChangePassword}>
                {passwordError && <p className="text-sm text-red-600 bg-red-50 rounded-lg p-3">{passwordError}</p>}

                {/* BUG-015: Current Password with eye toggle */}
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1.5">Current Password</label>
                  <div className="relative">
                    <input
                      type={showCurrentPassword ? 'text' : 'password'}
                      required
                      value={currentPassword}
                      onChange={(e) => setCurrentPassword(e.target.value)}
                      className="w-full border border-slate-200 rounded-xl px-4 py-2.5 pr-10 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 focus:border-[#4C1D95]"
                    />
                    <button
                      type="button"
                      onClick={() => setShowCurrentPassword((v) => !v)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700 transition-colors"
                      tabIndex={-1}
                    >
                      {showCurrentPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  </div>
                </div>

                {/* BUG-015: New Password with eye toggle */}
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1.5">New Password</label>
                  <div className="relative">
                    <input
                      type={showNewPassword ? 'text' : 'password'}
                      required
                      minLength={8}
                      value={newPassword}
                      onChange={(e) => setNewPassword(e.target.value)}
                      className="w-full border border-slate-200 rounded-xl px-4 py-2.5 pr-10 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 focus:border-[#4C1D95]"
                    />
                    <button
                      type="button"
                      onClick={() => setShowNewPassword((v) => !v)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700 transition-colors"
                      tabIndex={-1}
                    >
                      {showNewPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  </div>
                  <p className="text-xs text-slate-500 mt-1.5">At least 8 characters, with an uppercase letter, lowercase letter, number, and symbol.</p>
                </div>

                {/* BUG-015: Confirm Password with eye toggle */}
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1.5">Confirm New Password</label>
                  <div className="relative">
                    <input
                      type={showConfirmPassword ? 'text' : 'password'}
                      required
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      className="w-full border border-slate-200 rounded-xl px-4 py-2.5 pr-10 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 focus:border-[#4C1D95]"
                    />
                    <button
                      type="button"
                      onClick={() => setShowConfirmPassword((v) => !v)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700 transition-colors"
                      tabIndex={-1}
                    >
                      {showConfirmPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                    </button>
                  </div>
                </div>

                <div className="pt-4 border-t border-slate-100 flex justify-end">
                  <button
                    type="submit"
                    disabled={changingPassword}
                    className="flex items-center gap-2 bg-[#4C1D95] text-white px-6 py-2.5 rounded-xl text-sm font-semibold hover:bg-[#3b1574] transition-colors disabled:opacity-50"
                  >
                    {changingPassword ? <Loader2 size={16} className="animate-spin" /> : <Check size={16} />}
                    {changingPassword ? 'Updating...' : 'Change Password'}
                  </button>
                </div>
              </form>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';
import { useEffect, useRef, useState } from 'react';
import { PortalHeader } from '@/components/portal/PortalSidebar';
import { StatusBadge } from '@/components/ui/StatusBadge';
import { supportTicketService, SupportTicketRead, SupportTicketCommentRead } from '@/services/portalServices';
import { fileManagerService } from '@/services/moduleServices';
import { useToastStore } from '@/store/toastStore';
import { LifeBuoy, Loader2, Plus, Send, X, Paperclip, FileText } from 'lucide-react';

const CATEGORIES = ['general', 'billing', 'technical', 'campaign', 'creative'];
const PRIORITIES = ['low', 'medium', 'high', 'urgent'];

export default function SupportTicketsPage() {
  const [tickets, setTickets] = useState<SupportTicketRead[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [showCreate, setShowCreate] = useState(false);
  const [selected, setSelected] = useState<SupportTicketRead | null>(null);
  const showToast = useToastStore((s) => s.showToast);

  const load = () => {
    setLoading(true);
    setError(false);
    supportTicketService
      .getAll({ page_size: 100 })
      .then((res) => setTickets(res?.items ?? []))
      .catch(() => setError(true))
      .finally(() => setLoading(false));
  };

  useEffect(load, []);

  if (loading) {
    return (
      <div>
        <PortalHeader title="Support Tickets" subtitle="Raise and track requests to Amplivo" />
        <div className="flex items-center justify-center h-[60vh]">
          <Loader2 size={32} className="animate-spin text-[#4C1D95]" />
        </div>
      </div>
    );
  }

  return (
    <div>
      <PortalHeader title="Support Tickets" subtitle="Raise and track requests to Amplivo" />
      <div className="p-6 space-y-5">
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-700 text-sm rounded-xl p-4">
            Couldn&apos;t load support tickets. <button onClick={load} className="underline font-medium">Retry</button>
          </div>
        )}

        <div className="flex items-center justify-between">
          <p className="text-sm text-slate-500">{tickets.length} ticket{tickets.length !== 1 ? 's' : ''}</p>
          <button
            onClick={() => setShowCreate(true)}
            className="flex items-center gap-2 bg-[#4C1D95] text-white text-sm font-medium px-4 py-2.5 rounded-xl hover:bg-[#3b1675] transition-colors"
          >
            <Plus size={16} /> New Ticket
          </button>
        </div>

        <div className="bg-white rounded-2xl border border-slate-200 divide-y divide-slate-100">
          {tickets.length === 0 ? (
            <div className="text-center py-16">
              <LifeBuoy size={32} className="mx-auto text-slate-300 mb-3" />
              <p className="text-sm text-slate-400">No support tickets yet</p>
            </div>
          ) : (
            tickets.map((t) => (
              <button key={t.id} onClick={() => setSelected(t)} className="w-full text-left flex items-center justify-between gap-4 p-4.5 hover:bg-slate-50 transition-colors">
                <div className="flex-1 min-w-0">
                  <div className="font-semibold text-slate-900 text-sm truncate mb-1">{t.subject}</div>
                  <p className="text-xs text-slate-500 truncate mb-1.5">{t.description}</p>
                  <div className="flex items-center gap-3 text-xs text-slate-400">
                    <span className="capitalize font-medium text-slate-600">{t.category}</span>
                    <span>•</span>
                    <span className="capitalize font-medium text-slate-600">Priority: {t.priority}</span>
                    <span>•</span>
                    <span>{new Date(t.created_at).toLocaleDateString()}</span>
                  </div>
                </div>
                <div className="shrink-0 self-start mt-0.5">
                  <StatusBadge status={t.status} />
                </div>
              </button>
            ))
          )}
        </div>
      </div>

      {showCreate && <CreateTicketModal onClose={() => setShowCreate(false)} onCreated={(t) => { setTickets((p) => [t, ...p]); showToast('Support ticket created.', 'success'); }} />}
      {selected && <TicketDetailModal ticket={selected} onClose={() => setSelected(null)} />}
    </div>
  );
}

function CreateTicketModal({ onClose, onCreated }: { onClose: () => void; onCreated: (t: SupportTicketRead) => void }) {
  const [subject, setSubject] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('general');
  const [priority, setPriority] = useState('medium');
  const [submitting, setSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  // BUG-013: attachment state
  const [attachment, setAttachment] = useState<File | null>(null);
  const [uploadingAttachment, setUploadingAttachment] = useState(false);
  const attachmentRef = useRef<HTMLInputElement>(null);
  const showToast = useToastStore((s) => s.showToast);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!subject.trim() || !description.trim()) {
      setErrorMsg('Subject and description are required.');
      return;
    }
    setSubmitting(true);
    setErrorMsg('');
    try {
      let attachmentNote = '';
      // BUG-013: Upload attachment if provided, append URL to description
      if (attachment) {
        setUploadingAttachment(true);
        try {
          const uploaded = await fileManagerService.uploadBinary(attachment);
          const apiOrigin = (process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000/api/v1').replace(/\/api\/v1\/?$/, '');
          const url = uploaded.url.startsWith('http') ? uploaded.url : `${apiOrigin}${uploaded.url}`;
          attachmentNote = `\n\n📎 Attachment: ${uploaded.original_name} - ${url}`;
        } catch {
          showToast('Warning: Could not upload attachment. Ticket will be submitted without it.', 'error');
        } finally {
          setUploadingAttachment(false);
        }
      }

      const ticket = await supportTicketService.create({
        subject: subject.trim(),
        description: description.trim() + attachmentNote,
        category,
        priority,
      });
      onCreated(ticket);
      onClose();
    } catch {
      setErrorMsg('Failed to create ticket. Please try again.');
      showToast('Failed to create ticket.', 'error');
    } finally {
      setSubmitting(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] ?? null;
    setAttachment(file);
  };

  const removeAttachment = () => {
    setAttachment(null);
    if (attachmentRef.current) attachmentRef.current.value = '';
  };

  return (
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-bold text-slate-900">New Support Ticket</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X size={18} /></button>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          {errorMsg && <p className="text-sm text-red-600 bg-red-50 rounded-lg p-2">{errorMsg}</p>}
          <div>
            {/* BUG-012: Required asterisk on Subject label */}
            <label className="block text-xs font-medium text-slate-500 mb-1">
              Subject <span className="text-red-500">*</span>
            </label>
            <input
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              required
              className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/30"
              placeholder="Brief summary of your request"
            />
          </div>
          <div>
            {/* BUG-012: Required asterisk on Description label */}
            <label className="block text-xs font-medium text-slate-500 mb-1">
              Description <span className="text-red-500">*</span>
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              required
              rows={4}
              className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/30"
              placeholder="Describe your issue or request in detail"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Category</label>
              <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm capitalize">
                {CATEGORIES.map((c) => <option key={c} value={c} className="capitalize">{c}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-500 mb-1">Priority</label>
              <select value={priority} onChange={(e) => setPriority(e.target.value)} className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm capitalize">
                {PRIORITIES.map((p) => <option key={p} value={p} className="capitalize">{p}</option>)}
              </select>
            </div>
          </div>

          {/* BUG-013: Attachment upload field */}
          <div>
            <label className="block text-xs font-medium text-slate-500 mb-1">Attachment <span className="text-slate-400 font-normal">(optional)</span></label>
            <input
              ref={attachmentRef}
              type="file"
              accept="image/*,.pdf,.doc,.docx,.txt,.zip"
              className="hidden"
              onChange={handleFileChange}
            />
            {attachment ? (
              <div className="flex items-center gap-3 p-3 bg-slate-50 border border-slate-200 rounded-lg">
                <div className="w-8 h-8 rounded-lg bg-purple-50 flex items-center justify-center shrink-0">
                  <FileText size={16} className="text-[#4C1D95]" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-slate-800 truncate">{attachment.name}</p>
                  <p className="text-xs text-slate-400">{(attachment.size / 1024).toFixed(1)} KB</p>
                </div>
                <button
                  type="button"
                  onClick={removeAttachment}
                  className="text-slate-400 hover:text-red-500 p-1 rounded transition-colors"
                >
                  <X size={14} />
                </button>
              </div>
            ) : (
              <button
                type="button"
                onClick={() => attachmentRef.current?.click()}
                className="flex items-center gap-2 px-4 py-2.5 border border-dashed border-slate-300 text-slate-500 hover:border-[#4C1D95] hover:text-[#4C1D95] rounded-lg text-sm font-medium w-full justify-center transition-colors"
              >
                <Paperclip size={15} />
                Attach Screenshot / File
              </button>
            )}
          </div>

          <div className="flex gap-2 pt-2">
            <button type="button" onClick={onClose} className="flex-1 border border-slate-200 rounded-lg py-2.5 text-sm font-medium text-slate-600">Cancel</button>
            <button
              type="submit"
              disabled={submitting || uploadingAttachment}
              className="flex-1 bg-[#4C1D95] text-white rounded-lg py-2.5 text-sm font-medium disabled:opacity-60 flex items-center justify-center gap-2"
            >
              {(submitting || uploadingAttachment) && <Loader2 size={14} className="animate-spin" />}
              {submitting ? 'Submitting...' : uploadingAttachment ? 'Uploading...' : 'Submit Ticket'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

function TicketDetailModal({ ticket, onClose }: { ticket: SupportTicketRead; onClose: () => void }) {
  const [comments, setComments] = useState<SupportTicketCommentRead[]>([]);
  const [loading, setLoading] = useState(true);
  const [reply, setReply] = useState('');
  const [sending, setSending] = useState(false);
  const showToast = useToastStore((s) => s.showToast);

  useEffect(() => {
    supportTicketService.getComments(ticket.id).then(setComments).catch(() => setComments([])).finally(() => setLoading(false));
  }, [ticket.id]);

  const handleReply = async () => {
    if (!reply.trim()) return;
    setSending(true);
    try {
      const c = await supportTicketService.addComment(ticket.id, reply.trim());
      setComments((prev) => [...prev, c]);
      setReply('');
    } catch {
      showToast('Failed to send reply.', 'error');
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-lg p-6 max-h-[85vh] flex flex-col" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-2">
          {/* BUG-014: subject clearly separated from status badge */}
          <h3 className="font-bold text-slate-900 truncate">{ticket.subject}</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 shrink-0 ml-2"><X size={18} /></button>
        </div>
        <div className="flex items-center gap-2 mb-4">
          {/* BUG-014: StatusBadge is standalone, not part of text */}
          <StatusBadge status={ticket.status} />
          <span className="text-xs text-slate-400 capitalize">{ticket.category} · {ticket.priority} priority</span>
        </div>
        <p className="text-sm text-slate-600 mb-4">{ticket.description}</p>

        <div className="flex-1 overflow-y-auto border-t border-slate-100 pt-3 space-y-3">
          {loading ? (
            <Loader2 size={20} className="animate-spin text-[#4C1D95] mx-auto" />
          ) : comments.length === 0 ? (
            <p className="text-xs text-slate-400 text-center py-4">No replies yet</p>
          ) : (
            comments.map((c) => (
              <div key={c.id} className="bg-slate-50 rounded-xl p-3">
                <p className="text-sm text-slate-700">{c.content}</p>
                <p className="text-[10px] text-slate-400 mt-1">{new Date(c.created_at).toLocaleString()}</p>
              </div>
            ))
          )}
        </div>

        <div className="flex gap-2 pt-3 border-t border-slate-100 mt-3">
          <input
            value={reply}
            onChange={(e) => setReply(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleReply()}
            placeholder="Write a reply..."
            className="flex-1 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/30"
          />
          <button onClick={handleReply} disabled={sending || !reply.trim()} className="bg-[#4C1D95] text-white rounded-lg px-4 disabled:opacity-40">
            <Send size={16} />
          </button>
        </div>
      </div>
    </div>
  );
}

