'use client';
import { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Menu, X, ChevronDown, ArrowRight } from 'lucide-react';
import { Logo } from '@/components/ui/Logo';

const navLinks = [
  { label: 'Home', href: '/' },
  {
    label: 'Services',
    href: '/services',
    children: [
      { label: 'Social Media Marketing', href: '/services/social-media-marketing' },
      { label: 'Performance Marketing', href: '/services/performance-marketing' },
      { label: 'SEO', href: '/services/search-engine-optimisation' },
      { label: 'Branding & Creative', href: '/services/branding-and-creative-design' },
      { label: 'Content Marketing', href: '/services/content-marketing' },
      { label: 'Lead Generation', href: '/services/lead-generation' },
      { label: 'Website Development', href: '/services/website-development' },
      { label: 'Marketing Automation', href: '/services/marketing-automation' },
      { label: 'Influencer Marketing', href: '/services/influencer-marketing' },
      { label: 'Video Marketing', href: '/services/video-marketing' },
    ],
  },
  { label: 'Industries', href: '/industries' },
  { label: 'Portfolio', href: '/portfolio' },
  { label: 'Case Studies', href: '/case-studies' },
  { label: 'Insights', href: '/insights' },
  { label: 'About', href: '/about' },
  { label: 'Careers', href: '/careers' },
  { label: 'Contact', href: '/contact' },
];

interface NavbarProps {
  alwaysSolid?: boolean;
}

export function Navbar({ alwaysSolid = false }: NavbarProps) {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [activeDropdown, setActiveDropdown] = useState<string | null>(null);
  const pathname = usePathname();

  useEffect(() => {
    const handler = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handler);
    return () => window.removeEventListener('scroll', handler);
  }, []);

  const isSolid = alwaysSolid || scrolled;

  const isActive = (href: string) => {
    if (href === '/') return pathname === '/';
    return pathname === href || pathname.startsWith(href + '/');
  };

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isSolid
          ? 'bg-white/97 backdrop-blur-md border-b border-slate-200 shadow-md'
          : 'bg-[#1a0540]/60 backdrop-blur-md border-b border-white/10'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-4 lg:py-0 min-h-[88px] flex flex-wrap items-center justify-between gap-2 lg:gap-4">
        {/* Logo */}
        <Logo variant={isSolid ? 'dark' : 'white'} size="md" />

        {/* Navigation Bar (Always Visible) */}
        <nav className="flex w-full order-last mt-3 lg:mt-0 lg:w-auto lg:order-none overflow-x-auto scrollbar-hide items-center gap-1 xl:gap-2 pb-2 lg:pb-0" aria-label="Primary">
          {navLinks.map((link) => {
            const linkActive = isActive(link.href);
            const hasActiveChild = link.children?.some((c) => isActive(c.href));
            const dropdownOpen = activeDropdown === link.label;
            return (
              <div
                key={link.label}
                className="relative shrink-0"
                onMouseEnter={() => link.children && setActiveDropdown(link.label)}
                onMouseLeave={() => setActiveDropdown(null)}
                onFocus={() => link.children && setActiveDropdown(link.label)}
                onBlur={(e) => {
                  if (!e.currentTarget.contains(e.relatedTarget as Node)) {
                    setActiveDropdown(null);
                  }
                }}
                onKeyDown={(e) => { if (e.key === 'Escape') setActiveDropdown(null); }}
              >
                <Link
                  href={link.href}
                  onClick={(e) => {
                    if (link.href === '/' && pathname === '/') {
                      e.preventDefault();
                      window.scrollTo({ top: 0, behavior: 'smooth' });
                    }
                  }}
                  aria-current={linkActive ? 'page' : undefined}
                  aria-haspopup={link.children ? 'true' : undefined}
                  aria-expanded={link.children ? dropdownOpen : undefined}
                  className={`flex items-center gap-0.5 xl:gap-1 px-2.5 xl:px-3 py-1.5 xl:py-2 rounded-lg text-xs xl:text-sm font-medium transition-colors whitespace-nowrap ${
                    isSolid
                      ? linkActive || hasActiveChild
                        ? 'text-[#4C1D95] font-bold bg-[#4C1D95]/5'
                        : 'text-slate-600 hover:text-[#4C1D95] hover:bg-[#4C1D95]/5'
                      : linkActive || hasActiveChild
                        ? 'text-white font-bold bg-white/10'
                        : 'text-white/85 hover:text-white hover:bg-white/10'
                  }`}
                >
                  {link.label}
                  {link.children && <ChevronDown size={14} aria-hidden="true" className={`transition-transform ${dropdownOpen ? 'rotate-180' : ''}`} />}
                </Link>

                {(linkActive || hasActiveChild) && (
                  <span className={`absolute bottom-0 left-2 right-2 xl:left-3 xl:right-3 h-0.5 rounded-full ${isSolid ? 'bg-[#4C1D95]' : 'bg-white'}`} />
                )}

                {/* Dropdown */}
                {link.children && dropdownOpen && (
                  <div role="menu" className="absolute top-full left-0 mt-1 w-64 bg-white rounded-2xl border border-slate-100 shadow-xl shadow-black/10 p-2 z-50" aria-label={`${link.label} submenu`}>
                    {link.children.map((child) => (
                      <Link
                        key={child.label}
                        href={child.href}
                        role="menuitem"
                        aria-current={isActive(child.href) ? 'page' : undefined}
                        className={`flex items-center px-4 py-2.5 rounded-xl text-sm transition-colors ${
                          isActive(child.href)
                            ? 'text-[#4C1D95] font-bold bg-[#4C1D95]/5'
                            : 'text-slate-600 hover:text-[#4C1D95] hover:bg-[#4C1D95]/5'
                        }`}
                      >
                        {child.label}
                      </Link>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </nav>

        {/* Right CTAs */}
        <div className="flex items-center gap-2 xl:gap-4 shrink-0">
          <Link
            href="/login"
            className={`text-xs xl:text-sm font-medium px-3.5 xl:px-5 py-2 xl:py-2.5 rounded-xl border transition-all whitespace-nowrap ${isSolid
              ? 'border-slate-200 text-slate-700 hover:border-[#4C1D95] hover:text-[#4C1D95]'
              : 'border-white/30 text-white hover:bg-white/10'
              }`}
          >
            Client Login
          </Link>
          <button
            onClick={() => setMobileOpen(!mobileOpen)}
            aria-label={mobileOpen ? 'Close navigation menu' : 'Open navigation menu'}
            aria-expanded={mobileOpen}
            aria-controls="mobile-nav-menu"
            className={`lg:hidden p-2 rounded-lg transition-colors ${isSolid ? 'text-slate-700 hover:bg-slate-100' : 'text-white hover:bg-white/10'}`}
          >
            {mobileOpen ? <X size={20} aria-hidden="true" /> : <Menu size={20} aria-hidden="true" />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {mobileOpen && (
        <div id="mobile-nav-menu" className="lg:hidden bg-white border-t border-slate-100 shadow-lg max-h-[80vh] overflow-y-auto" aria-label="Mobile">
          <div className="px-4 py-4 space-y-1">
            {navLinks.map((link) => {
              const linkActive = isActive(link.href);
              const hasActiveChild = link.children?.some((c) => isActive(c.href));
              return (
                <div key={link.label}>
                  <Link
                    href={link.href}
                    onClick={(e) => {
                      setMobileOpen(false);
                      if (link.href === '/' && pathname === '/') {
                        e.preventDefault();
                        window.scrollTo({ top: 0, behavior: 'smooth' });
                      }
                    }}
                    className={`block px-4 py-3 text-sm font-medium rounded-xl transition-colors ${
                      linkActive || hasActiveChild
                        ? 'text-[#4C1D95] font-bold bg-[#4C1D95]/5'
                        : 'text-slate-700 hover:text-[#4C1D95] hover:bg-[#4C1D95]/5'
                    }`}
                  >
                    {link.label}
                  </Link>
                  {link.children && (
                    <div className="ml-4 space-y-0.5">
                      {link.children.map((child) => (
                        <Link
                          key={child.label}
                          href={child.href}
                          onClick={() => setMobileOpen(false)}
                          className={`block px-4 py-2 text-xs rounded-lg transition-colors ${
                            isActive(child.href)
                              ? 'text-[#4C1D95] font-bold bg-[#4C1D95]/5'
                              : 'text-slate-500 hover:text-[#4C1D95]'
                          }`}
                        >
                          {child.label}
                        </Link>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
            <div className="pt-3 border-t border-slate-100 mt-2">
              <Link href="/login" onClick={() => setMobileOpen(false)} className="block w-full text-center px-4 py-3 text-sm font-medium border border-slate-200 text-slate-700 rounded-xl hover:border-[#4C1D95] hover:text-[#4C1D95]">
                Client Login
              </Link>
            </div>
          </div>
        </div>
      )}
    </header>
  );
}

'use client';
import { useState } from 'react';
import Link from 'next/link';

import { ArrowRight, X } from 'lucide-react';
import { portfolioItems } from '@/data/portfolio';
import { AnimateOnScroll } from '@/components/AnimateOnScroll';

type PortfolioItem = typeof portfolioItems[0];

export function PortfolioSection() {
  const featured = portfolioItems.slice(0, 6);
  const [selectedItem, setSelectedItem] = useState<PortfolioItem | null>(null);

  return (
    <section className="bg-white py-14">
      <div className="max-w-7xl mx-auto px-6">
        {/* Header */}
        <AnimateOnScroll animation="fade-up">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12">
            <div>
              <span className="inline-flex items-center gap-2 bg-[#4C1D95]/10 text-[#4C1D95] text-xs font-bold px-4 py-2 rounded-full mb-4 uppercase tracking-widest">
                Our Work
              </span>
              <h2 className="text-3xl lg:text-4xl font-bold text-slate-900" style={{ fontFamily: "'Sora', sans-serif" }}>
                Work We Are Proud Of
              </h2>
              <p className="text-slate-500 mt-2 max-w-md">From social campaigns to websites — our creative output across industries.</p>
            </div>
            <Link
              href="/portfolio"
              className="hidden md:inline-flex items-center gap-2 text-[#4C1D95] font-semibold text-sm hover:underline whitespace-nowrap"
            >
              View full portfolio <ArrowRight size={14} />
            </Link>
          </div>
        </AnimateOnScroll>

        {/* Grid */}
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 md:gap-5">
          {featured.map((item, i) => (
            <AnimateOnScroll key={item.id} animation="scale-in" delay={i * 80}>
              <div
                onClick={() => setSelectedItem(item)}
                className="relative group overflow-hidden rounded-2xl cursor-pointer h-52 md:h-60"
              >
                {/* Image */}
                <img
                  src={item.image}
                  alt={item.title}
                  className="absolute inset-0 w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                />

                {/* Always-visible bottom strip */}
                <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/75 to-transparent p-3 group-hover:opacity-0 transition-opacity duration-300">
                  <p className="text-white text-xs font-semibold truncate">{item.title}</p>
                  <p className="text-white/60 text-[10px] mt-0.5">{item.client}</p>
                </div>

                {/* Hover overlay */}
                <div className="absolute inset-0 bg-gradient-to-t from-[#0f0524]/95 via-[#1a0540]/70 to-[#4C1D95]/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-end p-4">
                  {/* Client badge */}
                  <div className="absolute top-3 right-3 bg-white/90 backdrop-blur-sm text-slate-800 text-[10px] font-bold px-2.5 py-1 rounded-full">
                    {item.client}
                  </div>

                  {/* Content slides up */}
                  <div className="transform translate-y-3 group-hover:translate-y-0 transition-transform duration-300">
                    <div className="text-[#06B6D4] text-[10px] font-bold uppercase tracking-widest mb-1">{item.category}</div>
                    <h3 className="text-white font-bold text-sm leading-snug mb-2">{item.title}</h3>
                    <div className="flex flex-wrap gap-1.5 mb-3">
                      {item.tags.slice(0, 3).map((tag) => (
                        <span key={tag} className="bg-white/20 text-white text-[10px] font-medium px-2 py-0.5 rounded-full border border-white/20">
                          {tag}
                        </span>
                      ))}
                    </div>
                    <button className="inline-flex items-center gap-1.5 text-white text-xs font-semibold bg-[#4C1D95] px-3 py-1.5 rounded-lg hover:bg-[#5b21b6] transition-colors">
                      View Project <ArrowRight size={12} />
                    </button>
                  </div>
                </div>
              </div>
            </AnimateOnScroll>
          ))}
        </div>

        {/* Mobile CTA */}
        <div className="mt-8 text-center md:hidden">
          <Link href="/portfolio" className="inline-flex items-center gap-2 text-[#4C1D95] font-semibold text-sm">
            View full portfolio <ArrowRight size={14} />
          </Link>
        </div>
      </div>

      {/* Modal */}
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-black/75 backdrop-blur-sm"
            onClick={() => setSelectedItem(null)}
          />
          <div className="relative bg-white rounded-3xl w-full max-w-4xl overflow-hidden flex flex-col md:flex-row shadow-2xl"
            style={{ animation: 'modalIn 0.25s ease-out' }}>
            {/* Close */}
            <button
              onClick={() => setSelectedItem(null)}
              className="absolute top-4 right-4 z-10 bg-slate-100 hover:bg-slate-200 text-slate-700 p-2 rounded-full transition-colors"
            >
              <X size={18} />
            </button>

            {/* Image */}
            <div className="w-full md:w-1/2 h-56 md:h-auto relative flex-shrink-0">
              <img
                src={selectedItem.image}
                alt={selectedItem.title}
                className="absolute inset-0 w-full h-full object-cover"
              />
            </div>

            {/* Content */}
            <div className="w-full md:w-1/2 p-8 md:p-10 flex flex-col justify-center">
              <div className="text-[#06B6D4] text-xs font-bold uppercase tracking-widest mb-2">
                {selectedItem.category}
              </div>
              <h3 className="text-2xl font-bold text-slate-900 mb-2 leading-tight" style={{ fontFamily: "'Sora', sans-serif" }}>
                {selectedItem.title}
              </h3>
              <div className="text-slate-500 text-sm mb-5">
                Client: <span className="font-semibold text-slate-800">{selectedItem.client}</span>
              </div>

              <div className="flex flex-wrap gap-2 mb-6">
                {selectedItem.tags.map((tag) => (
                  <span key={tag} className="bg-slate-100 text-slate-700 text-xs font-medium px-3 py-1 rounded-full">
                    {tag}
                  </span>
                ))}
              </div>

              <p className="text-slate-600 text-sm leading-relaxed mb-8">
                We partnered with <strong>{selectedItem.client}</strong> to design and execute a{' '}
                {selectedItem.category.toLowerCase()} strategy that delivered measurable growth —
                from increased brand visibility to real conversion improvements across channels.
              </p>

              <Link
                href="/contact"
                className="inline-flex items-center justify-center gap-2 bg-[#4C1D95] text-white font-semibold py-3 px-6 rounded-xl hover:bg-[#3b1574] transition-colors w-fit"
              >
                Discuss a Similar Project <ArrowRight size={16} />
              </Link>
            </div>
          </div>
        </div>
      )}

      <style jsx>{`
        @keyframes modalIn {
          from { opacity: 0; transform: scale(0.95) translateY(12px); }
          to   { opacity: 1; transform: scale(1)    translateY(0);     }
        }
      `}</style>
    </section>
  );
}

