'use client';
import { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';import { Logo } from '@/components/ui/Logo';
import { LayoutDashboard, Megaphone, TrendingUp, BarChart2, Image as ImageIcon,
  Files, Calendar, MessageSquare, FileText, LifeBuoy, Settings, LogOut, Zap, Bell,
  FolderKanban, Receipt, Folder, Menu, CheckCheck
} from 'lucide-react';
import { Avatar } from '@/components/ui/Avatar';
import { useAuthStore } from '@/store/authStore';
import { authService } from '@/services/authService';
import { campaignService } from '@/services/campaignService';
import { creativeService, companyService, messagingService } from '@/services';
import { userManagementService } from '@/services/crmService';
import { useUiStore } from '@/store/uiStore';

interface AccountManager {
  name: string;
  email: string;
}

function useSidebarData() {
  const [activeCampaigns, setActiveCampaigns] = useState(0);
  const [pendingCreatives, setPendingCreatives] = useState(0);
  const [unreadMessages, setUnreadMessages] = useState(0);
  const [accountManager, setAccountManager] = useState<AccountManager | null>(null);
  const { user } = useAuthStore();

  useEffect(() => {
    let cancelled = false;

    async function load() {
      try {
        const campaignsRes = await campaignService.getAll({ page_size: 100 });
        const items = campaignsRes?.items ?? [];
        if (!cancelled) setActiveCampaigns(items.filter((c: { status?: string }) => c.status === 'Active').length);
      } catch {
        // leave at 0
      }

      try {
        const projectsRes = await creativeService.getProjects({ page_size: 20 });
        const projects = projectsRes?.items ?? projectsRes ?? [];
        let pending = 0;
        for (const p of projects.slice(0, 5)) {
          try {
            const assets = await creativeService.getAssets(p.id);
            pending += (assets ?? []).filter((a: { status?: string }) => (a.status ?? '').toLowerCase() === 'pending').length;
          } catch {
            // skip project on error
          }
        }
        if (!cancelled) setPendingCreatives(pending);
      } catch {
        // leave at 0
      }

      try {
        const convRes = await messagingService.getConversations({ page_size: 5 });
        const conversations = convRes?.items ?? [];
        let unread = 0;
        for (const c of conversations) {
          try {
            const messages = await messagingService.getMessages(c.id);
            unread += messages.filter((m) => !m.is_read && m.sender_id !== user?.id).length;
          } catch {
            // skip conversation on error
          }
        }
        if (!cancelled) setUnreadMessages(unread);
      } catch {
        // leave at 0
      }

      try {
        const company = await companyService.getMine();
        if (company.assigned_to) {
          const manager = await userManagementService.getUser(company.assigned_to);
          let name = manager.full_name ?? manager.name ?? 'Account Manager';
          let email = manager.email ?? '';
          if (name === 'Admin User' || email === 'admin@amplivo.in') {
            name = 'Account Manager';
            email = 'support@amplivo.in';
          }
          if (!cancelled) setAccountManager({ name, email });
        }
      } catch {
        // no account manager assigned / not a client-portal user
      }
    }

    load();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return { activeCampaigns, pendingCreatives, unreadMessages, accountManager };
}

export function PortalSidebar() {
  const pathname = usePathname();
  const router = useRouter();
  const { user, logout, refreshToken } = useAuthStore();
  const { activeCampaigns, pendingCreatives, unreadMessages, accountManager } = useSidebarData();
  const { isSidebarOpen, setSidebarOpen } = useUiStore();
  const [lastSeenCampaigns, setLastSeenCampaigns] = useState(0);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('lastSeenCampaigns');
      if (stored) setLastSeenCampaigns(parseInt(stored, 10));
    }
  }, []);

  useEffect(() => {
    if (pathname === '/portal/campaigns' && activeCampaigns > 0) {
      setLastSeenCampaigns(activeCampaigns);
      if (typeof window !== 'undefined') {
        localStorage.setItem('lastSeenCampaigns', activeCampaigns.toString());
      }
    }
  }, [pathname, activeCampaigns]);

  const newCampaigns = Math.max(0, activeCampaigns - lastSeenCampaigns);

  const navItems = [
    { icon: LayoutDashboard, label: 'Dashboard', href: '/portal' },
    { icon: Megaphone, label: 'Campaigns', href: '/portal/campaigns', badge: newCampaigns > 0 ? String(newCampaigns) : undefined },
    { icon: ImageIcon, label: 'Creative Approval', href: '/portal/creatives', badge: pendingCreatives > 0 ? String(pendingCreatives) : undefined },
    { icon: TrendingUp, label: 'Leads', href: '/portal/leads' },
    { icon: FolderKanban, label: 'Projects & Tasks', href: '/portal/projects' },
    { icon: Calendar, label: 'Content Calendar', href: '/portal/calendar' },
    { icon: BarChart2, label: 'SEO Reports', href: '/portal/seo' },
    { icon: Files, label: 'Analytics', href: '/portal/analytics' },
    { icon: FileText, label: 'Invoices', href: '/portal/invoices' },
    { icon: Receipt, label: 'Payments', href: '/portal/payments' },
    { icon: Folder, label: 'Documents', href: '/portal/documents' },
    { icon: MessageSquare, label: 'Messages', href: '/portal/messages', badge: unreadMessages > 0 ? String(unreadMessages) : undefined },
    { icon: LifeBuoy, label: 'Support Tickets', href: '/portal/support' },
  ];

  const handleLogout = async () => {
    try {
      if (refreshToken) await authService.logout(refreshToken);
    } catch {
      // ignore
    } finally {
      logout();
      router.push('/login');
    }
  };

  return (
    <>
      {/* Mobile Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/50 z-40 md:hidden" 
          onClick={() => setSidebarOpen(false)}
        />
      )}
      <aside className={`
        fixed md:sticky top-0 left-0 z-50 h-screen w-64 flex-shrink-0 bg-[#111827] flex flex-col overflow-hidden
        transition-transform duration-300 ease-in-out
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
      `}>
      {/* Logo */}
      <div className="flex items-center gap-3 px-5 h-16 border-b border-[#1F2937]">
        <Logo size="sidebar" variant="white" href="/portal" />
      </div>

      {/* User Info — BUG-018: use user?.image so sidebar updates when avatar changes */}
      <div className="px-5 py-4 border-b border-[#1F2937]">
        <div className="flex items-center gap-3">
          <Avatar name={user?.name ?? 'Client'} image={user?.image} size="sm" />
          <div className="min-w-0">
            <div className="text-white text-sm font-semibold truncate">{user?.name ?? 'Client'}</div>
            <div className="text-[#4B5563] text-xs truncate">{user?.company ?? user?.email ?? ''}</div>
          </div>
        </div>
      </div>

      {/* Nav */}
      <nav className="flex-1 px-3 py-4 space-y-0.5 overflow-y-auto">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={() => setSidebarOpen(false)}
              className={`flex items-center gap-3 px-3 py-2.5 rounded-[10px] transition-all text-sm ${
                isActive
                  ? 'bg-[#4C1D95] text-white'
                  : 'text-[#9CA3AF] hover:bg-[#1F2937] hover:text-white'
              }`}
            >
              <item.icon size={17} className="flex-shrink-0" />
              <span className="flex-1">{item.label}</span>
              {item.badge && (
                <span className="bg-[#7C3AED] text-white text-[10px] px-1.5 py-0.5 rounded-full font-bold">
                  {item.badge}
                </span>
              )}
            </Link>
          );
        })}
      </nav>

      {/* Footer / Sign Out */}
      <div className="px-4 py-4 border-t border-[#1F2937]">
        <div className="flex gap-2">
          <button onClick={handleLogout} className="flex items-center gap-2 px-3 py-2 rounded-[10px] text-[#9CA3AF] hover:bg-[#1F2937] hover:text-red-400 transition-all text-xs flex-1">
            <LogOut size={14} /> Sign Out
          </button>
          <Link href="/portal/settings" className="flex items-center justify-center w-9 h-9 rounded-[10px] text-[#9CA3AF] hover:bg-[#1F2937] hover:text-white transition-all">
            <Settings size={15} />
          </Link>
        </div>
      </div>
    </aside>
    </>
  );
}

// Portal Top Header — shared across all portal pages, shows real user + real notifications
interface PortalHeaderProps {
  title: string;
  subtitle?: string;
}
export function PortalHeader({ title, subtitle }: PortalHeaderProps) {
  // BUG-018: read user from auth store so avatar reflects latest upload
  const { user } = useAuthStore();
  const { toggleSidebar } = useUiStore();
  const [open, setOpen] = useState(false);
  const [notifications, setNotifications] = useState<Array<{ id: string; title?: string; message: string; is_read: boolean; created_at: string }>>([]);
  const [loading, setLoading] = useState(true);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let cancelled = false;
    import('@/services/crmService').then(({ notificationService }) => {
      notificationService
        .getAll({ page_size: 10 })
        .then((res) => {
          if (!cancelled) setNotifications(res?.items ?? []);
        })
        .catch(() => {})
        .finally(() => {
          if (!cancelled) setLoading(false);
        });
    });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    function onClickOutside(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, []);

  const unreadCount = notifications.filter((n) => !n.is_read).length;

  // BUG-06: Auto-close popup when all notifications become read
  useEffect(() => {
    if (open && unreadCount === 0 && !loading && notifications.length > 0) {
      setOpen(false);
    }
  }, [unreadCount, open, loading, notifications.length]);

  const handleMarkRead = async (id: string) => {
    const { notificationService } = await import('@/services/crmService');
    try {
      await notificationService.markRead(id);
      setNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, is_read: true } : n)));
    } catch {
      // ignore
    }
  };

  // BUG-06: Mark all as read from within the popup and close it
  const handleMarkAllRead = async () => {
    const { notificationService } = await import('@/services/crmService');
    try {
      await notificationService.markAllRead();
      setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));
      setOpen(false); // close popup after marking all as read
    } catch {
      // ignore
    }
  };

  return (
    <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 md:px-6 flex-shrink-0 sticky top-0 z-10 gap-4">
      <div className="flex items-center gap-3 min-w-0">
        <button 
          onClick={toggleSidebar}
          className="md:hidden text-slate-500 hover:text-slate-900 focus:outline-none shrink-0"
        >
          <Menu size={20} />
        </button>
        <div className="min-w-0">
          <h1 className="text-base md:text-lg font-bold text-slate-900 truncate" style={{ fontFamily: "'Sora', sans-serif" }}>{title}</h1>
          {subtitle && <p className="text-xs text-slate-400 truncate">{subtitle}</p>}
        </div>
      </div>
      <div className="flex items-center gap-2 md:gap-3 shrink-0">
        <div className="relative" ref={ref}>
          <button
            onClick={() => setOpen((o) => !o)}
            className="relative w-9 h-9 rounded-[10px] bg-slate-50 border border-slate-200 flex items-center justify-center text-slate-500 hover:text-slate-900 transition-colors"
          >
            <Bell size={17} />
            {unreadCount > 0 && (
              <span className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-[#EC4899] text-white text-[9px] font-bold flex items-center justify-center">
                {unreadCount > 9 ? '9+' : unreadCount}
              </span>
            )}
          </button>
          {open && (
            <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl border border-slate-200 shadow-lg overflow-hidden">
              <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between">
                <span className="text-sm font-semibold text-slate-900">Notifications</span>
                <div className="flex items-center gap-2">
                  {/* BUG-06: Mark all read button inside popup */}
                  {unreadCount > 0 && (
                    <button
                      onClick={handleMarkAllRead}
                      className="text-xs text-[#4C1D95] hover:underline flex items-center gap-1"
                      title="Mark all as read"
                    >
                      <CheckCheck size={12} />
                      Mark all read
                    </button>
                  )}
                  <Link href="/portal/notifications" className="text-xs text-slate-400 hover:underline" onClick={() => setOpen(false)}>
                    View all
                  </Link>
                </div>
              </div>
              <div className="max-h-80 overflow-y-auto">
                {loading ? (
                  <p className="text-xs text-slate-400 text-center py-6">Loading...</p>
                ) : notifications.length === 0 ? (
                  <p className="text-xs text-slate-400 text-center py-6">No notifications</p>
                ) : (
                  notifications.slice(0, 6).map((n) => (
                    <button
                      key={n.id}
                      onClick={() => handleMarkRead(n.id)}
                      className="w-full text-left px-4 py-3 border-b border-slate-50 hover:bg-slate-50 flex gap-2"
                    >
                      <div className={`w-1.5 h-1.5 rounded-full mt-1.5 flex-shrink-0 ${n.is_read ? 'bg-slate-300' : 'bg-amber-500'}`} />
                      <div className="min-w-0">
                        <p className="text-xs text-slate-700 line-clamp-2">{n.title ? `${n.title}: ` : ''}{n.message}</p>
                        <p className="text-[10px] text-slate-400 mt-0.5">{new Date(n.created_at).toLocaleString()}</p>
                      </div>
                    </button>
                  ))
                )}
              </div>
            </div>
          )}
        </div>
        {/* BUG-018: Avatar reads from user?.image which is updated by login() on avatar upload */}
        <Avatar name={user?.name ?? 'Client'} image={user?.image} size="sm" />
      </div>
    </header>
  );
}

'use client';
import { useState } from 'react';
import { X, User, Building2, Mail, Phone, TrendingUp, Star, AlertCircle, FileText } from 'lucide-react';
import { useSalesStore } from '@/store/salesStore';
import { ServiceSelector } from './ServiceSelector';

import { SalesLead } from '@/types';

interface AddLeadModalProps {
  onClose: () => void;
  leadToEdit?: SalesLead;
}

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Accepts an optional leading +, then 7-15 digits, allowing spaces/hyphens as
// separators - loose enough for Indian and international formats alike.
const PHONE_REGEX = /^\+?[\d\s-]{7,17}$/;

interface FieldErrors {
  title?: string;
  firstName?: string;
  companyName?: string;
  email?: string;
  phone?: string;
  budget?: string;
}

export function AddLeadModal({ onClose, leadToEdit }: AddLeadModalProps) {
  const { createLead, editLead } = useSalesStore();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});

  const [form, setForm] = useState({
    title: leadToEdit?.title || '',
    firstName: leadToEdit?.firstName || '',
    lastName: leadToEdit?.lastName || '',
    companyName: leadToEdit?.company || '',
    email: leadToEdit?.email || '',
    phone: leadToEdit?.phone || '',
    budget: leadToEdit?.budget || 0,
    priority: (leadToEdit?.priority || 'Medium') as 'Low' | 'Medium' | 'High' | 'Critical',
    notes: leadToEdit?.notes || '',
  });

  const [interestedServices, setInterestedServices] = useState<string[]>(leadToEdit?.interestedServices || []);

  // Mirrors what a visitor must fill in on the public "Book Free Growth Audit"
  // form (frontend/src/app/contact/page.tsx): Name, Company, and Email are
  // mandatory there too; Phone/Service/Budget/Message are optional on both.
  const validate = (): FieldErrors => {
    const errors: FieldErrors = {};
    if (!form.title.trim()) errors.title = 'Lead Title is required.';
    if (!form.firstName.trim()) errors.firstName = 'Name is required.';
    if (!form.companyName.trim()) errors.companyName = 'Company name is required.';
    if (!form.email.trim()) {
      errors.email = 'Email is required.';
    } else if (!EMAIL_REGEX.test(form.email.trim())) {
      errors.email = 'Enter a valid email address.';
    }
    if (form.phone.trim() && !PHONE_REGEX.test(form.phone.trim())) errors.phone = 'Enter a valid phone number (7-15 digits).';
    if (form.budget < 0) errors.budget = 'Budget cannot be negative.';
    return errors;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const errors = validate();
    setFieldErrors(errors);
    if (Object.keys(errors).length > 0) {
      setError(null);
      return;
    }

    setLoading(true);
    setError(null);

    const contactName = `${form.firstName} ${form.lastName}`.trim();

    try {
      const payload = {
        title: form.title,
        company_name: form.companyName || undefined,
        contact_name: contactName || undefined,
        email: form.email || undefined,
        phone: form.phone || undefined,
        priority: form.priority,
        estimated_value: form.budget || undefined,
        notes: form.notes || undefined,
        interested_services: interestedServices.length > 0 ? interestedServices : undefined,
      };

      if (leadToEdit) {
        await editLead(leadToEdit.id, payload);
      } else {
        await createLead(payload);
      }
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : `Failed to ${leadToEdit ? 'save' : 'create'} lead. Please check the details and try again.`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      
      {/* Modal Container (Scrollable) */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-2xl border border-slate-200 animate-fade-in-up flex flex-col max-h-[90vh] overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-slate-100 flex-shrink-0">
          <div>
            <h2 className="font-bold text-slate-900 text-lg" style={{ fontFamily: "'Sora', sans-serif" }}>
              {leadToEdit ? 'Edit Lead' : 'Add New Lead'}
            </h2>
            <p className="text-sm text-slate-500 mt-0.5">
              {leadToEdit ? 'Update the details for this pipeline lead' : 'Initialize a new opportunity in the pipeline'}
            </p>
          </div>
          <button
            onClick={onClose}
            className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-600 transition-colors"
          >
            <X size={18} />
          </button>
        </div>

        {/* Form Body (Scrollable) */}
        <form onSubmit={handleSubmit} className="flex-1 flex flex-col min-h-0 overflow-hidden">
          <div className="p-6 space-y-6 flex-1 overflow-y-auto">
          {error && (
            <div className="p-4 bg-red-50 border border-red-200 rounded-xl flex items-center gap-3 text-red-700 text-sm">
              <AlertCircle size={18} className="flex-shrink-0 text-red-500" />
              <span>{error}</span>
            </div>
          )}

          {/* Primary Lead Title */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">
              Lead Title <span className="text-red-500">*</span>
            </label>
            <div className="relative">
              <FileText size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input
                type="text"
                required
                aria-required="true"
                placeholder="e.g. Website Overhaul Campaign, Custom Software retention"
                value={form.title}
                onChange={(e) => {
                  setForm({ ...form, title: e.target.value });
                  setFieldErrors((prev) => ({ ...prev, title: undefined }));
                }}
                className={`w-full pl-10 pr-3 py-2.5 border rounded-xl text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 ${
                  fieldErrors.title ? 'border-red-400' : 'border-slate-200 focus:border-[#4C1D95]'
                }`}
              />
            </div>
            {fieldErrors.title && <p className="mt-1.5 text-xs text-red-500 font-medium">{fieldErrors.title}</p>}
          </div>

          {/* Name Details */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">
                First Name <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <User size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="text"
                  required
                  aria-required="true"
                  placeholder="John"
                  value={form.firstName}
                  onChange={(e) => {
                    setForm({ ...form, firstName: e.target.value });
                    setFieldErrors((prev) => ({ ...prev, firstName: undefined }));
                  }}
                  className={`w-full pl-10 pr-3 py-2.5 border rounded-xl text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 ${
                    fieldErrors.firstName ? 'border-red-400' : 'border-slate-200 focus:border-[#4C1D95]'
                  }`}
                />
              </div>
              {fieldErrors.firstName && <p className="mt-1.5 text-xs text-red-500 font-medium">{fieldErrors.firstName}</p>}
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">Last Name</label>
              <div className="relative">
                <User size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="text"
                  placeholder="Doe"
                  value={form.lastName}
                  onChange={(e) => setForm({ ...form, lastName: e.target.value })}
                  className="w-full pl-10 pr-3 py-2.5 border border-slate-200 rounded-xl text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 focus:border-[#4C1D95]"
                />
              </div>
            </div>
          </div>

          {/* Contact Details */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">
                Email Address <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <Mail size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="email"
                  required
                  aria-required="true"
                  placeholder="john.doe@company.com"
                  value={form.email}
                  onChange={(e) => {
                    setForm({ ...form, email: e.target.value });
                    setFieldErrors((prev) => ({ ...prev, email: undefined }));
                  }}
                  className={`w-full pl-10 pr-3 py-2.5 border rounded-xl text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 ${
                    fieldErrors.email ? 'border-red-400' : 'border-slate-200 focus:border-[#4C1D95]'
                  }`}
                />
              </div>
              {fieldErrors.email && <p className="mt-1.5 text-xs text-red-500 font-medium">{fieldErrors.email}</p>}
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">Phone Number</label>
              <div className="relative">
                <Phone size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="tel"
                  placeholder="+91 98765 43210"
                  value={form.phone}
                  onChange={(e) => {
                    setForm({ ...form, phone: e.target.value });
                    setFieldErrors((prev) => ({ ...prev, phone: undefined }));
                  }}
                  className={`w-full pl-10 pr-3 py-2.5 border rounded-xl text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 ${
                    fieldErrors.phone ? 'border-red-400' : 'border-slate-200 focus:border-[#4C1D95]'
                  }`}
                />
              </div>
              {fieldErrors.phone && <p className="mt-1.5 text-xs text-red-500 font-medium">{fieldErrors.phone}</p>}
            </div>
          </div>

          {/* Company details & budget */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">
                Company Name <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <Building2 size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="text"
                  required
                  aria-required="true"
                  placeholder="Acme Corp"
                  value={form.companyName}
                  onChange={(e) => {
                    setForm({ ...form, companyName: e.target.value });
                    setFieldErrors((prev) => ({ ...prev, companyName: undefined }));
                  }}
                  className={`w-full pl-10 pr-3 py-2.5 border rounded-xl text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 ${
                    fieldErrors.companyName ? 'border-red-400' : 'border-slate-200 focus:border-[#4C1D95]'
                  }`}
                />
              </div>
              {fieldErrors.companyName && <p className="mt-1.5 text-xs text-red-500 font-medium">{fieldErrors.companyName}</p>}
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">Monthly Budget (₹)</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm font-semibold">₹</span>
                <input
                  type="number"
                  min={0}
                  placeholder="50000"
                  value={form.budget || ''}
                  onChange={(e) => {
                    setForm({ ...form, budget: Number(e.target.value) });
                    setFieldErrors((prev) => ({ ...prev, budget: undefined }));
                  }}
                  className={`w-full pl-7 pr-3 py-2.5 border rounded-xl text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 ${
                    fieldErrors.budget ? 'border-red-400' : 'border-slate-200 focus:border-[#4C1D95]'
                  }`}
                />
              </div>
              {fieldErrors.budget && <p className="mt-1.5 text-xs text-red-500 font-medium">{fieldErrors.budget}</p>}
            </div>
          </div>

          {/* Priority */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">Priority Level</label>
            <div className="flex gap-2">
              {(['Low', 'Medium', 'High', 'Critical'] as const).map((lvl) => {
                const isActive = form.priority === lvl;
                return (
                  <button
                    key={lvl}
                    type="button"
                    onClick={() => setForm({ ...form, priority: lvl })}
                    className={`flex-1 py-2 px-3 rounded-xl border text-xs font-semibold transition-all ${
                      isActive
                        ? lvl === 'Critical' ? 'bg-red-50 border-red-200 text-red-600 shadow-sm font-bold' :
                          lvl === 'High' ? 'bg-orange-50 border-orange-200 text-orange-600 shadow-sm font-bold' :
                          lvl === 'Medium' ? 'bg-amber-50 border-amber-200 text-amber-600 shadow-sm font-bold' :
                          'bg-slate-100 border-slate-200 text-slate-700 shadow-sm font-bold'
                        : 'bg-white border-slate-200 text-slate-500 hover:bg-slate-50'
                    }`}
                  >
                    {lvl}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Interested Services */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">Interested Services</label>
            <ServiceSelector
              selected={interestedServices}
              onChange={setInterestedServices}
            />
          </div>

          {/* Notes */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wider mb-2">Initial Notes</label>
            <textarea
              placeholder="Provide background information, requirements or meeting notes..."
              value={form.notes}
              onChange={(e) => setForm({ ...form, notes: e.target.value })}
              rows={4}
              className="w-full px-3 py-2.5 border border-slate-200 rounded-xl text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-[#4C1D95]/20 focus:border-[#4C1D95] resize-none"
            />
          </div>

          {/* Footer Actions */}
          </div>
          {/* Bug 18 fixed: footer is outside the scrollable area so it stays visible */}
          <div className="flex gap-3 p-6 pt-4 border-t border-slate-100 flex-shrink-0">
            <button
              type="button"
              onClick={onClose}
              disabled={loading}
              className="flex-1 px-4 py-3 border border-slate-200 text-slate-600 rounded-xl text-sm font-semibold hover:bg-slate-50 transition-colors disabled:opacity-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading}
              className="flex-1 px-4 py-3 bg-[#4C1D95] text-white rounded-xl text-sm font-semibold hover:bg-[#3b1574] transition-colors shadow-sm disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  {leadToEdit ? 'Saving...' : 'Creating...'}
                </>
              ) : (
                leadToEdit ? 'Save Changes' : 'Create Lead'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { getInitials } from '@/lib/utils';

interface AvatarProps {
  name: string;
  image?: string;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  className?: string;
}

const sizeMap = {
  xs: 'w-7 h-7 text-xs',
  sm: 'w-9 h-9 text-sm',
  md: 'w-11 h-11 text-sm',
  lg: 'w-14 h-14 text-base',
};

export function Avatar({ name, image, size = 'sm', className = '' }: AvatarProps) {
  const [imgError, setImgError] = useState(false);
  const sizeClass = sizeMap[size];

  if (image && !imgError) {
    return (
      <img
        src={image}
        alt={name || 'Avatar'}
        onError={() => setImgError(true)}
        className={`${sizeClass} rounded-full object-cover flex-shrink-0 ${className}`}
      />
    );
  }

  return (
    <div
      className={`${sizeClass} rounded-full bg-[#4C1D95] text-white flex items-center justify-center flex-shrink-0 font-bold select-none ${className}`}
    >
      <span>{getInitials(name)}</span>
    </div>
  );
}

